quests[35982] = { id = 35982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 12" }
quests[35983] = { id = 35983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Hansel Event Complete" }
quests[35984] = { id = 35984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 13" }
quests[35985] = { id = 35985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Zerschlagene Anhöhe", description = "Ihr da! Ihr seid hier der Kommandant, stimmt's? Ich vertrete die Interessen der Werterhaltungsgesellschaft des Dampfdruckkartells.\n\nWir versuchen schon seit einer Weile, in Nagrand eine sehr wichtige Ausgrabung in Gange zu bringen. Leider machen uns die Oger in der Gegend etwas Schwierigkeiten.\n\nEiner unserer besten Werterhalter ist beim Vermessen des Gebiets sogar kürzlich verschwunden. Er ist schon der dritte, den wir diese Woche da oben verloren haben!\n\nWir sind nicht wirklich für eine Rettungsaktion ausgerüstet... wollt Ihr uns helfen? Wir könnten die Unterstützung wirklich gebrauchen.", sourceObjective = "Findet Greblin Flinkzünd.", completion = "Ihr sucht was? Ich meine, ja, klar... schon in Ordnung. Holt mich einfach nur runter, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[35986] = { id = 35986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 021 - Knochengeschnitzter Dolch" }
quests[35987] = { id = 35987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 025 - Trümmer der Genedar" }
quests[35988] = { id = 35988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "<Die wabernde arkane Energie scheint Leute durch Eure Garnison zu führen.>\n\nKommandant {name}! Ich wurde geschickt, um Euch zu holen.\n\nErzmagier Khadgar möchte Euch um einen sehr dringenden Gefallen bitten. Er macht sich ernste Sorgen wegen zusätzlicher Gefahren, die diese Welt für Azeroth darstellen könnte, und er braucht Eure Unterstützung, um sich darum zu kümmern. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.\n\nEs wird nicht lange dauern.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", completion = "<Der Erzmagier sieht durchnässt aus und fühlt sich offensichtlich unwohl.>\n\nBitte entschuldigt die Bedingungen hier, {name}. Mir blieb keine andere Wahl. Ich habe diesen Turm am optimalen Zusammenfluss arkaner Energien beschworen. Hoffentlich ist meine Arbeit hier beendet, bevor noch all meine Bücher schimmelig werden.\n\nNun denn! Machen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[35989] = { id = 35989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Aufgabe", description = "Diese Welt birgt viele Gefahren für die Unseren. In erster Linie die Eiserne Horde. Eure Garnison und die gesamte Macht Eurer Armee sind auf diesen Widersacher ausgerichtet. Aber für mich selbst habe ich ein anderes Ziel im Kopf.\n\nGul'dan.\n\nHier, macht es Euch bequem. Nehmt Euch etwas Manastrudel. Ich erzähle Euch von meinem Plan, während ich Euren Ring erschaffe...", sourceObjective = "Sprecht mit Khadgar in seinem Turm in Zangarra.", completion = "Euer Ring ist fertig. Das ist aber nur der erste Schritt. Wenn wir mehr Zeit zusammen verbringen, können wir einen Ring von legendärer Macht erschaffen. Aber eins nach dem anderen!\n\nGul'dan könnte sich überall verborgen halten, aber wenn wir einen seiner Leutnants finden, können wir ihn sicher aus seinem Versteck treiben. Sammeln wir zunächst einmal die magischen Reagenzien, die ich brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[35990] = { id = 35990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenkern", description = "Verglichen mit Azeroth ist Draenor eine junge Welt. Die Naturgewalten, die es formten und gestalteten, sind immer noch zugänglich... wenn man weiß, wo.\n\nIhr müsst mir einen Flammenkern suchen. Die Oger der Blutschläger können diese geschmolzenen Furien nach ihrem Willen formen, aber Ihr und ich können damit sehr viel Besseres anfangen.\n\nGeht in die Blutschlägermine und besorgt Euch einen von Gug'rokk. Wenn er tot ist, wird er ihn nicht mehr brauchen.", sourceObjective = "Besorgt einen Flammenkern von Gug'rokk in der Blutschlägermine [nur Heroisch].", progress = "Wart Ihr schon bei der Blutschlägermine?\n\nMal ehrlich, die bauen da Schlacke ab? Was wollen die denn damit?", completion = "<Khadgar rollt die feurige Kugel zwischen seinen Händen hin und her.>\n\nWisst Ihr, wie man das benutzt, {name}?\n\nIch auch nicht. Manchmal muss man eben improvisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[35991] = { id = 35991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenkern", description = "Es hat keinen Zweck, einen Flammenkern zu besorgen, wenn wir seine Energie nicht fokussieren können. Irgendwie haben die Goblins herausgefunden, wie das geht. Die Technologie wird in den Maschinen der \"eisernen Sterne\" verwendet, die die Eiserne Horde in ganz Draenor einsetzt. Wir brauchen den größten Antriebskern, den wir finden können.\n\nAm besten lassen wir einen ihrer Züge entgleisen und brechen die Lokomotive auf. Ich schlage einen Überfall auf das Grimmgleisdepot vor...", sourceObjective = "Besorgt einen Eisenkern aus dem Zug aus dem Grimmgleisdepot [nur Heroisch].", progress = "Habt Ihr den Antriebskern?\n\nNormalerweise würde ich Euch ja nicht bitten, einen gepanzerten, fahrenden Zug zu überfallen... ach was. Eigentlich ist es genau das, wozu ich Euch brauche. Ständig.", completion = "Oh, sehr gut. So einen wollte ich mir schon lange mal ansehen. Öffnen wir ihn gleich hier.\n\nHmmmmm...\n\nTja, sehr kreativ sind diese Goblins ja nicht, aber ihre Methoden haben einen gewissen groben Charme. Erstaunlich, dass dieses Ding nicht explodiert. Oder vielleicht tut es das ja. Jedenfalls verstehe ich allmählich, wozu sie ein \"Samophlang\" brauchen.\n\nDamit wird es wird gehen. Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[35992] = { id = 35992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenskern", description = "Wahrsagen für ein lebendes Wesen ist eine sehr spezielle Art von Magie, und wenn wir ganz Draenor nach Gul'dan absuchen wollen, brauchen wir ein sehr mächtiges lebendes Reagenz.\n\nDie Antwort liegt im Pflanzenreich von Draenor selbst. Es gibt eine Kreatur namens \"Genesaurier\", die den urtümlichen Kreaturen, die alles Leben auf dieser Erde begründet haben, am nächsten kommt.\n\nEiner unserer Außenposten der Kirin Tor in Gorgrond wurde überrannt, und ein Genesaurier namens \"Yalnu\" wurde dabei gesichtet. Tötet ihn und bringt mir sein Herz!", sourceObjective = "Besorgt einen Lebenskern, indem Ihr Yalnu im Immergrünen Flor tötet [Nur Heroisch].", progress = "Wie steht es mit dem Außenposten? Und vor allem... Wo ist mein Lebenskern?", completion = "Oh... Er lebt noch! Spürt Ihr das?\n\nEr muss in die Erde Draenors zurückkehren, wenn wir mit ihm fertig sind... vielleicht in die Obhut des Zirkels des Cenarius, der dafür sorgen kann, dass er sich nicht zu einer weiteren verderbten Bedrohung auswächst.\n\nGut gemacht, {name}. Das war keine leichte Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[35993] = { id = 35993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf mit Teron'gor", description = "Ich habe gerade eine schlimme Nachricht von Exarch Maladaar erhalten, die uns aber helfen könnte. Agenten des Schattenrats sind in Auchindoun eingedrungen! Ich wette, dass Gul'dans Schergen dahinterstecken... wahrscheinlich der Orc Teron'gor, seine rechte Hand.\n\nNehmen wir ihn aus dem Spiel, {name}. Tötet Teron'gor!\n\nBringt mir eine Phiole mit seinem verderbten Blut, dann kann ich damit andere Unruhestifter des Schattenrates ausfindig machen... einschließlich Gul'dan. Unsere Beute wird sich nicht mehr verstecken können.", sourceObjective = "Besorgt verderbtes Blut von Teron'gor in Auchindoun [nur Heroisch].", progress = "Was gibt es Neues aus Auchindoun? Sind die Draeneigeister sicher?\n\nHatte ich Recht mit Teron'gor?", completion = "Heute haben wir Großes erreicht, {name}. Wir haben Gul'dan einen seiner engsten Vertrauten geraubt und sind dem Unhold selbst einen Schritt nähergekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[35994] = { id = 35994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Erzmagiers", description = "Mit Teron'gors Blut und den Kristallen, die Ihr für mich gesammelt habt, sollte ich in der Lage sein, unser Ziel anzuvisieren. Geht mit mir hinaus, und ich werde meinen Wahrsagezauber beginnen. Sprecht am Anfang mit mir zusammen... und seid auf alles vorbereitet!", sourceObjective = "Sprecht mit Khadgar und verteidigt ihn, während er seinen Seherzauber anwendet.", completion = "Gul'dan kämpft gegen meine Magie an, {name}! Er versteckt sich!\n\nEr ist zwar begabt, aber wir sind ihm überlegen. Ich glaube, ich weiß, wie ich die Kraft und die Reichweite meines Zaubers erhöhen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[35995] = { id = 35995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befleckte Bronze", description = "Die Essenz des toten Drachen scheint in die Struktur dieser lichtvergessenen Welt eingedrungen zu sein. Und auch sein Geist ist ruhelos. Wenn wir beide uns seine verbliebene Kraft sichern wollen, müssen wir zu Ende bringen, was Garrosh begonnen hat.\n\nIch werde mich auf Eure taktische Kampferfahrung verlassen müssen, Kommandant. Wollt Ihr lieber angreifen, defensiv kämpfen oder uns heilen?\n\nDiese Entscheidung überlasse ich Euch. Sprecht mich an, wenn Ihr bereit seid. Dann werden wir drei Kairoz endgültig vernichten.", sourceObjective = "Sprecht mit Erzmagier Khadgar, um Eure bevorzugte Rolle zu wählen und den Geist von Kairozdormu zu besiegen.", completion = "<Der Erzmagier ist außer Atem.>\n\nIch brauche... nur einen kleinen Moment. Puh.\n\n{name}, das war unglaublich! Ihr seid womöglich der beste {class}, an dessen Seite ich jemals kämpfen durfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[35996] = { id = 35996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Tiefenwurz" }
quests[35997] = { id = 35997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Imperiums", description = "Der Ogerzaubererkönig, Kaiser Mar'gok, beherrscht magische Techniken, die wir als arkane Grenzwissenschaften betrachten würden. Seine Teufelsbrecher, um nur ein Beispiel zu nennen, können Magie bewusst mindern oder absorbieren. Sogar Teufelsmagie!\n\nWenn wir Gul'dan finden wollen, müssen wir herausfinden, wie das funktioniert. Nehmt seinem Teufelsbrecherhauptmann den Teufelsbrecherfolianten und dem Zaubererkönig selbst sein Siegelzeichen ab. Ich muss wissen, was er weiß.\n\nJa, {name}, das bedeutet, dass Ihr Hochfels erstürmen und alle Verteidiger dort besiegen müsst. Also an die Arbeit!", sourceObjective = "Beschafft den Teufelsbrecherfolianten und das Siegelzeichen des Zaubererkönigs aus Hochfels.", progress = "Was habt Ihr in Hochfels gefunden?", completion = "Der Teufelsbrecherfoliant ist leer? Lasst mich mal sehen. Habt Ihr das Siegelzeichen des Zaubererkönigs? Ah, ja... Seht mal: Wenn man mit dem Siegelzeichen über die Seite fährt, tauchen dort Runenschriftzeichen auf. Oh... Das ist wirklich raffiniert.\n\nEs wird vermutlich eine Weile dauern, bis ich Eure Entdeckung gänzlich verstehen kann, {name}. Aber auf diesen ersten Seiten wird die Teufelsenergie charakterisiert. Das ist genau, was ich brauche! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[35998] = { id = 35998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis der Zaubererkönige", sourceObjective = "Beschafft 125 Dominanzsteine von den Kreaturen in Hochfels. In bestimmten Missionen können auch Eure Garnisonsanhänger solche Steine finden.", progress = "Habt Ihr die Steine? Ich hätte nie gedacht, dass ich einmal auf Ogermagie zurückgreifen würde. Aber diese uralten Zaubererkönige wussten ein paar Sachen über pure arkane Energie, die die Gelehrten der Kirin Tor jahrelang beschäftigen würden.", completion = "<Khadgar hält einige der Steine ins Licht, wodurch Strahlen arkaner Energie von Stein zu Stein springen.>\n\nIch glaube kaum, dass ich die Oger noch einmal unterschätzen werde, {name}. Ein oder zwei intelligente Vertreter können aus all den anderen eine schlagkräftige Armee bilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[35999] = { id = 35999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 071 - Genedar Debris" }
quests[36000] = { id = 36000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüchtiger Drache", description = "Bereit für die Drachenjagd? Ein Bronzedrache hat Garrosh Höllschrei befreit und ihn in diese Welt gebracht. Sein Name ist Kairozdormu und er ist ein Flüchtling aus Azeroth. Wir müssen ihn ausfindig machen.\n\nDiese gesamte Zeitlinie ist von seiner Essenz durchdrungen. Wenn ich ihn nur finden könnte – tot oder lebendig! – wäre ich in der Lage, meine Magie auf dieses Zeitalter Draenors zu rekalibrieren.\n\nAber dazu brauchen wir die Hilfe eines weiteren Mitglieds seines Schwarms. Ich werde sie aufspüren und anschließend in Nagrand zu Euch stoßen. Wir treffen uns an der Kreuzung nördlich des Rings der Prüfung.", sourceObjective = "Trefft Euch mit Khadgar nördlich des Rings der Prüfung in Nagrand.", completion = "{name}, Chromie hier hat zugestimmt, uns bei der Suche nach unserem Bronzeflüchtling zu helfen.\n\nSie mag klein und niedlich aussehen, aber ich kann Euch versichern, dass sie hundert Mal so alt ist wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[36001] = { id = 36001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 14" }
quests[36002] = { id = 36002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 072 - Trümmer der Genedar" }
quests[36003] = { id = 36003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 15" }
quests[36004] = { id = 36004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Macht", description = "Ihr habt Euch wirklich eine Belohnung verdient, Kommandant. Ich werde hier alles einpacken und wir treffen uns dann wieder bei meinem Turm. Ihr könnt mein Portal verwenden, um direkt dorthin zu gelangen.\n\nSprecht mich an, wenn Ihr dort eingetroffen seid. Dann werde ich Kairoz' Kräfte zusammen mit den Kristallen, die Ihr gefunden habt, verwenden und Euren Ring verstärken!", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra, damit er Euren Ring verstärkt.", completion = "Wie geht es Euch? Möchtet Ihr etwas zu trinken?\n\nIch wünschte, ich könnte behaupten, dass von jetzt an alles einfacher wird, aber wir stehen leider erst am Anfang. Ich muss Euch bitten, direkt in das Herz des Ogerreiches vorzustoßen... Seid Ihr bereit dazu?", sourceObjectiveStatus = "unverified-source-field" }
quests[36005] = { id = 36005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zweite Gesicht", description = "Wir haben von den Ogern alles gelernt, was wir brauchen, {name}. Dank Eurer Anstrengungen kann ich Gul'dan jetzt hinter seinem Schleier der Verstohlenheit hervorziehen.\n\nIch WERDE ihn finden, {class}.\n\nWenn mein Zauber fertig ist, sind wir bereit, unverzüglich zur Tat zu schreiten. Aber ich werde damit so lange warten, bis Ihr mir signalisiert, dass Ihr bereit seid.", sourceObjective = "Sprecht mit Khadgar und findet Gul'dan mit dem Seherzauber.", completion = "Man hat auf ihn eingestochen!\n\nWarum war er so sorglos? Wir hätten Wachen einsetzen können, wir hätten...\n\nAber das ist jetzt egal. Wir müssen umgehend handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[36006] = { id = 36006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger: Gejagt", description = "Die Waffe, die dem Erzmagier in den Leib gerammt wurde, war mit Teufelsmagie durchwirkt. Er wird jetzt ganz langsam vergiftet!\n\n{name}, wir haben nicht viel Zeit. Khadgar wird in wenigen Minuten sterben. Ihr müsst Garona finden, bevor sie entkommen kann. Wenn wir die Mordwaffe haben, können wir vielleicht noch ein Gegenmittel herstellen!\n\nFolgt den Teufelsenergiespuren, die sie hinterlassen hat. Sucht sie im Tiefland von Zangarra und nehmt sie mit Hilfe dieser Kerkerrune der Violetten Festung gefangen.\n\nBeeilt Euch!", sourceObjective = "Folgt Garonas Spur ins Tiefland von Zangarra. Findet sie, besiegt sie und nehmt sie gefangen.", completion = "Die Kirin Tor haben blitzschnell reagiert. Jaina war in wenigen Minuten hier. Aber wenn Ihr Garona nicht gefunden hättet, wäre der Erzmagier mit Sicherheit gestorben. Ich danke Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[36007] = { id = 36007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Kirin Tor", description = "<Khadgar atmet schwer und sieht sehr bleich aus, aber in seinen Augen blitzt immer noch pure Energie auf.>\n\nIhr habt mir das Leben gerettet, {name}. Wieder einmal habe ich Gul'dan unterschätzt – und fast alles verloren.\n\nKommt, helft mir auf. Jaina hier kann mir dabei helfen, Euren Ring zu verstärken. Ihr habt es Euch verdient! Sagt mir einfach Bescheid, wenn Ihr bereit dazu seid.", sourceObjective = "Sprecht mit Erzmagier Khadgar, um Euren Ring verstärken zu lassen.", completion = "Wie fühlt sich das an?\n\nEuer Ring zählt jetzt zu den mächtigsten Artefakten dieser Welt. Und das ist auch gut so, denn schon bald werden wir den Feind frontal angreifen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36008] = { id = 36008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 073 - Genedar Debris" }
quests[36009] = { id = 36009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Zorns", description = "Es ist töricht, Gul'dan nur mit magischen Mitteln zu verfolgen. Aber dank Euch haben wir eine Gefangene: Garona. Wenn wir Gul'dans Gedankenkontrolle über sie beenden können, werden wir all seine Geheimnisse erfahren.\n\nEs wird mir gelingen, aber dafür benötige ich einige mächtige Zauberkomponenten.\n\nAls erstes brauche ich das Herz eines Elementarzorns. In der Schwarzfelsgießerei wird einer von ihnen gefangen gehalten. Bahnt Euch einen Weg dort hinein, zerstört den Schmelzofen und tötet den Elementar darin.", sourceObjective = "Besiegt den im Schmelzofen der Schwarzfelsgießerei gefangenen Elementarzorn und entnehmt ihm das Herz des Zorns.", progress = "Diese \"Elementarzorne\" auf Draenor sind einzigartig. Vielleicht liegt es an der Urtümlichkeit dieser Welt.", completion = "Vorsicht! Ganz vorsichtig! Setzt es einfach dort ab. Ich kümmere mich jetzt darum.\n\nMit dem Herz eines Zorns muss man umsichtig umgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36010] = { id = 36010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Flammenbändiger", description = "Die Eiserne Horde, und insbesondere die Brennende Klinge, sind einen einzigartigen Bund mit Draenors uralten Elementaren eingegangen. Sie sind in der Lage, auf eine Weise mit Eisen und Feuer zu arbeiten, die selbst ich noch nicht ganz nachvollziehen kann.\n\nNoch nicht.\n\n{name}, Ihr müsst die höchstrangige Kunsthandwerkerin der Brennenden Klinge töten: Flammenbändigerin Ka'graz. Ihr findet sie ganz unten in der Schwarzen Schmiede der Schwarzfelsgießerei, an einem Ort, den man den Feuerbrunnen nennt. Wenn wir Glück haben, sind ihre Geheimnisse im Folianten der Flammenbändiger verzeichnet.", sourceObjective = "Beschafft den Folianten der Flammenbändiger von Flammenbändigerin Ka'graz in der Schwarzfelsgießerei.", progress = "Habt Ihr den Folianten der Flammenbändiger? Viele legendäre Waffen der Brennenden Klinge verdanken ihre Existenz diesem Werk!", completion = "Lasst mich mal sehen, was Ihr da habt... Sehr interessant! Diese andere Runensprache scheint dem Ignan-Kalimag-Dialekt der Feuerelementare von Azeroth sehr ähnlich zu sein. Eine vollständige Übersetzung könnte Jahre in Anspruch nehmen.\n\nAber diese orcischen Passagen... Die könnte ich wohl recht schnell entziffern. Nicht nur, um Stahl zu verarbeiten, sondern vielmehr, um uns die Elementarkräfte selbst gefügig zu machen.\n\nGul'dan mag ja sehr mächtig sein, aber wenn wir weiterhin die Geheimnisse von Draenor offenbaren, werden wir auf jeden seiner Schritte eine Antwort haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[36011] = { id = 36011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 074 - Genedar Debris" }
quests[36012] = { id = 36012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgekehrte Piraterie", description = "{name}, während des Angriffs auf Karabor haben die Schlachtschiffe der Eisernen Horde die meisten Schiffe der östlichen Draeneiflotte geplündert oder versenkt. Dabei haben sie auch ein unersetzliches Artefakt erbeutet: Eine echte thaumaturgische Kugel der Draenei.\n\nIch brauche diese Kugel! Diese Orcs haben ja keine Ahnung, was sie da an sich genommen haben!\n\nMeine Quellen besagen, dass sich die Kugel an Bord eines Schiffes befand, das zurzeit in der Entsetzlichen Grotte unterhalb der Schwarzfelsgießerei umgebaut wird. Durchsucht das Schiff und seine Umgebung nach der Lade der Sha'tar, in der die Kugel aufbewahrt wurde. Wir müssen sie zurückbekommen!", sourceObjective = "Beschafft die thaumaturgische Kugel der Draenei aus der Entsetzlichen Grotte in der Schwarzfelsgießerei.", progress = "Die Kugel! Habt Ihr wirklich die Kugel gefunden...?", completion = "Ihr habt sie gefunden! Ich habe schon so viel über diese mächtigen Kugeln gehört. Ich wollte sie immer während meines langen Exils in der Scherbenwelt studieren. Und jetzt habe ich endlich eine. Zeigt mal her...\n\n<Ehrfurchtsvoll öffnet Khadgar Eure Tasche und schaut hinein. Für eine lange Weile bleibt seine Mimik ausdruckslos. Dann sagt er:>\n\nIch weiß nicht, was ich erwartet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[36013] = { id = 36013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht der Elementarlords", description = "Der Schwarzfelsklan hat es irgendwie geschafft, ein Bündnis mit den Kreaturen des Feuers und der Felsen einzugehen. Und ich muss herausfinden, wie sie das geschafft haben!\n\nIhr müsst die gesamte Schwarzfelsgießerei durchsuchen. Sucht nach Steintafeln, die auf die vorgeschichtlichen Zeiten von Draenor datiert sind. Vermutlich sind sie in einzelne Teile zerbrochen, die Ihr finden und zusammensetzen müsst. Bei den hochrangigen Mitgliedern solltet Ihr die entsprechenden Elementarrunen finden.\n\nSetzt sie zusammen und bringt mir dann diese Tafeln, {name}. Ich werde ihre Kraft verwenden, um Euren Ring zu verstärken!", sourceObjective = "Sammelt 3 Elementartafeln. Beschafft die Tafeln, indem Ihr Bosse in der Schwarzfelsgießerei besiegt und ihnen ihre Elementarrunen abnehmt.", progress = "Ich konnte ein wenig Zeit darauf verwenden, die Vorgeschichte von Draenor zu studieren. Im sogenannten Zeitalter der Giganten kämpften die Urelementare gegeneinander um die Ausformung der Welt. Und ihre Nachfahren kämpfen heute noch darum, insbesondere in Regionen wie Gorgrond.\n\nDie Tafeln, die Ihr beschaffen müsst, zeigen die Kräfte während dieser Zeit auf und, was noch viel wichtiger ist, sie ermöglichen uns, diese Kräfte zu kontrollieren und zu kanalisieren – so wie es der Schwarzfelsklan jetzt schon tut!", completion = "Ihr habt die Tafeln. Sehr gut! Es muss sehr zeitraubend und gefährlich gewesen sein, sie zusammenzusetzen. Ich kann mich glücklich schätzen, dass es Euch gibt.\n\nAber jetzt will ich zur Tat schreiten. Zeigt mir Euren Ring. Ja, das sollte möglich sein. Ich werde jetzt diese Tafeln dazu verwenden, um Eure Kraft zu stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[36014] = { id = 36014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfausts Geheimnis", description = "{name}, ich habe mich mit Eurem Mitbringsel beschäftigt. Im Folianten der Flammenbändiger gibt es einen Abschnitt über \"Opfer\" und einen neueren Zusatzeintrag über \"den Häuptling\". Ich glaube, es handelt sich dabei um den Kriegsherrn Schwarzfaust.\n\nHat Schwarzfaust jemanden geopfert? Oder sich selbst? Oder einen Teil von sich selbst? Ist deswegen seine Hand deformiert?\n\nBevor ich es riskieren kann, diese Elemente für einen Zauber zu verwenden, muss ich es genau wissen. Und es gibt nur einen Weg, es herauszufinden.\n\nTötet den Kriegsherrn Schwarzfaust und bringt mir seinen abgetrennten Arm.", sourceObjective = "Tötet Kriegsherr Schwarzfaust in der Schwarzfelsgießerei und nehmt seinen abgetrennten Arm an Euch.", progress = "Und, {name}? Arm dran oder Arm ab?", completion = "Was haben wir denn da? Dann sind die Legenden wirklich WAHR. Schwarzfaust hat seinen eigenen Arm den Elementen geopfert. Jetzt, wo er tot ist, kann man ihn kaum von einem Stein unterscheiden. Oder?\n\n<Khadgar murmelt ein paar Sprüche aus dem Folianten der Flammenbändiger. Die abgetrennte Hand bildet langsam eine Faust.>\n\nHmmmm. Ja. {name}, ich will ganz ehrlich zu Euch sein: Das Ding ist wirklich extrem gruselig.", sourceObjectiveStatus = "unverified-source-field" }
quests[36015] = { id = 36015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 16" }
quests[36016] = { id = 36016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ungebrochene Kreis", description = "Durch das Lesen dieser Tafeln kann man sich in die Zeiten zur Entstehung von Draenor zurückversetzen. Ich spüre hier eine Macht, die größer ist als alles, was ich je gesehen habe, seit ich Medivhs Schüler war. Ich glaube, sie kontrollieren zu können. Aber könnt auch Ihr damit umgehen?\n\nWenn Ihr denkt, dass Ihr so weit seid, dann macht Euch bereit. Haltet den Ring dicht an Euer Herz. Ich werde dann pure Elementarenergie durch ihn hindurchfließen lassen.\n\nSagt mir einfach, wenn ich beginnen soll!", sourceObjective = "Sprecht mit Erzmagier Khadgar, um Euren Ring verstärken zu lassen.", completion = "<Khadgar scheint äußerst besorgt.>\n\nEs tut mir sehr leid, Kommandant. Einen Augenblick lang dachte ich, wir hätten Euch für immer verloren.\n\nDieser Ring wird Euch gute Dienste leisten. Ich habe noch nie ein so mächtiges und perfektes Artefakt gesehen. Man kann ihn vielleicht noch weiter verstärken, aber... ich weiß nicht, welche Risiken damit verbunden sind.\n\nVerwendet Euren Ring mit Bedacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[36017] = { id = 36017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangener des Geistes", description = "Ich hatte einige Zeit, um den Folianten der Flammenbeugerin mit den Elementartafeln, die Ihr gesammelt habt, zu vergleichen. Interessant wird es, wenn ich die Beschwörungen, die Ihr von den Teufelsbrecherogern erbeutet habt, damit abgleiche... Ich merke schon, Ihr könnt mir nicht folgen. Ich fasse mal zusammen: Ich glaube, ich kann einen Zauber wirken, der Gul'dans geistige Kontrolle über seine Attentäterin Garona zunichte macht.\n\nGeistige Kontrolle oder nicht, sie könnte gefährlich sein, also werde ich mit dem Zauber erst beginnen, wenn Ihr dabei seid. Lasst mich wissen, wenn Ihr so weit seid!", sourceObjective = "Sprecht mit Khadgar und beschützt ihn, während er seinen Zauber auf Garona wirkt.", completion = "Gul'dans Magie ist tief in Garonas Geist verankert. Je mehr Zeit ich mit ihr verbringe, desto deutlicher wird es, dass wir sie von seiner Kontrolle befreien MÜSSEN.\n\nIch werde keinesfalls aufgeben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36018] = { id = 36018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind noch nicht fertig...", description = "{name}, ich werde mich in meine Bücher stürzen müssen, um weitere Forschungen darüber anzustellen, wie man Gul'dan aufspüren oder seine geistige Kontrolle über Garona brechen kann. Das ist zwar keine glorreiche Arbeit, aber das Leben eines Magiers besteht oft aus langen Stunden mühsamer Studien.\n\nSoweit es Euch betrifft, so gibt es viel zu tun. Stellt sicher, dass unsere Garnison auf dem neuesten Stand ist, findet die bestmögliche Ausrüstung und führt den Kampf gegen die Eiserne Horde fort.\n\nIch werde Euch rufen, wenn der nächste Schritt Eurer Reise bevorsteht.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[36019] = { id = 36019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 17" }
quests[36020] = { id = 36020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 026 - Oshu'gun Fragment" }
quests[36021] = { id = 36021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 036 - Pokhar's Thirteenth Axe" }
quests[36022] = { id = 36022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motivation von außen", description = "Der Zerschmetterten Hand sind Schmerzen nicht fremd. Sie alle schneiden sich als Zeichen ihrer Ergebenheit gegenüber Kargath die eigene Hand ab.\n\nWenn Ihr sie zum Reden bringen wollt, braucht es dazu womöglich mehr als mein Gift.\n\nMetzelt sie alle nieder. Wir werden ja sehen, wie weit sie für ihren geliebten Kriegsfürsten zu gehen bereit sind.", sourceObjective = "Tötet 4 blinde Kämpfer der Zerschmetterten Hand, 3 Ausschlachter der Zerschmetterten Hand und 1 Blutsänger der Zerschmetterten Hand.", completion = "Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[36023] = { id = 36023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motivation von außen", description = "Der Zerschmetterten Hand sind Schmerzen nich' fremd. Sie alle schneid'n sich als Zeichen ihrer Treue zu Kargath die eig'ne Hand ab.\n\nWenn Ihr die Informationen krieg'n wollt, die wir brauch'n, braucht Ihr womöglich mehr als mein Gift.\n\nMetzelt sie alle nieder. Wir werd'n ja sehen, wie weit sie für ihr'n geliebt'n Kriegsfürsten geh'n wollen.", sourceObjective = "Tötet 4 blinde Kämpfer der Zerschmetterten Hand, 3 Ausschlachter der Zerschmetterten Hand und 1 Blutsänger der Zerschmetterten Hand.", completion = "Sie haben bekommen, was sie verdient haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36024] = { id = 36024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Gute Arbeit, {class}. Wir werden Euch nicht enttäuschen." }
quests[36025] = { id = 36025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede MENGE Artefaktfragmente" }
quests[36026] = { id = 36026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Artefaktfragmente" }
quests[36027] = { id = 36027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stab des Erzmagiers Vargoth", sourceObjective = "Ah, {name}. Es ist wunderbar, Euch zu \"sehen\". Wie Ihr zweifellos wisst, zerfällt die Scherbenwelt in unserer Zeitlinie immer mehr.\n\nIch möchte meine Dienste Eurer Sache aus der Ferne zur Verfügung stellen, damit ich Draenor in der Zeit, bevor es in Stücke gerissen wurde, besser untersuchen kann.\n\nDiese Projektion mag durchsichtig erscheinen, aber ich kann Euch versichern, dass sie als perfekter Katalysator für meine Kräfte dient.\n\nWollt Ihr meine Dienste akzeptieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[36028] = { id = 36028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gardul Giftdolch", description = "Wir müssen Gardul ausschalten und ihm sein Giftrezept abnehmen, solange das Überraschungsmoment auf unserer Seite ist. Wir brauchen es, um ein Gegenmittel herzustellen. Das ist vielleicht unsere einzige Chance.\n\nWenn Eure Informationen stimmen, dann ist sein Lager unmittelbar südlich. Ihr schaltet ihn aus, und ich sorge dafür, dass sich seine Wachen nicht einmischen.\n\nLos.", sourceObjective = "Besiegt Gardul Giftdolch bei der Zerschmetterten Anhöhe.", completion = "Er wird uns nicht entkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36029] = { id = 36029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gardul Giftdolch", description = "Wir müss'n Gardul ausschalten und ihm sein Giftrezept nehmen, solange das Überraschungsmoment auf unsrer Seite ist. Wir brauch'n das Rezept, um ein Gegenmittel zu find'n. Das ist vielleicht unsre einzige Chance.\n\nWenn Eure Informationen stimmen, dann ist sein Lager nur etwas südlich von hier. Ihr schaltet ihn aus, und ich sorg' dafür, dass sich seine Wachen nich' einmischen.", sourceObjective = "Besiegt Gardul Giftdolch bei der Zerschmetterten Anhöhe.", completion = "Er wird uns nicht entkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36030] = { id = 36030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
quests[36031] = { id = 36031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Gute Arbeit, {class}. Wir werden Euch nicht enttäuschen." }
quests[36032] = { id = 36032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede MENGE Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Gute Arbeit, {class}. Wir werden Euch nicht enttäuschen." }
quests[36033] = { id = 36033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeschlagener Nachtelfenkopf", progress = "IHRE KÖPFE! BRINGT MIR DIE KÖPFE DIESER NICHT-TAGESLICHT-ELFEN!", completion = "WIE HÜÜÜBSCH. WIE GEMACHT FÜR DEN PFAHL VOR MEINER HÜTTE. HAHAHA. HIER, NEHMT DIESE BELOHNUNG UND GEHT WIEDER." }
quests[36034] = { id = 36034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenrückgrat", progress = "SIE FLUTSCHEN EINFACH SO RAUS, WAS?", completion = "OOOOH! DIE IST ABER MAL LANG. HE HE HAHAAH. HIER, NEHMT DAS ALS BELOHNUNG." }
quests[36035] = { id = 36035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 075 - Polierter Saberonschädel" }
quests[36036] = { id = 36036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 076 - Elemental Manacles" }
quests[36037] = { id = 36037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zenturio ohne Ziel", sourceObjective = "Dieser Dschungel wird mich umbringen, und ich kehre nicht zurück, um auf Knien nach Mar'goks Gnade zu betteln!\n\nIch habe bereits mehrere Kriege durchlebt und Feldzüge auf zwei Kontinenten bestritten. Wenn Ihr mir einen lohnenswerten Krieg bietet, will ich mich gerne eine Weile anschließen.\n\nZumindest so lange, bis ich den Zaubererkönig töten kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[36038] = { id = 36038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandarenfell", progress = "MOMENT MAL... DIESEN BALG HABT IHR DOCH NICHT ETWA VON EINEM PANDAREN DER HORDE, ODER?", completion = "EGAL, WER MAG SCHON PANDAS! <Lacht> NEHMT DIESE BELOHNUNG UND GEHT WIEDER!" }
quests[36039] = { id = 36039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 077 - Ogre Hammer" }
quests[36040] = { id = 36040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Büschel Gnomhaar", progress = "IST DAS... EIN GNOMENKOPF?", completion = "MOMENT MAL, IHR HABT MIR BLOSS DAS HAAR GEBRACHT? UGH. ICH WOLLTE DOCH IHRE KÖPFE! UGHHH! <Stampft mit den Füßen.> ABER ES REICHT WOHL ALS BEWEIS, DASS IHR GEGEN EINEN GEKÄMPFT HABT, ALSO NEHMT EURE BELOHNUNG. UND NÄCHSTES MAL BRINGT IHR MIR DEN KOPF!" }
quests[36041] = { id = 36041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draeneischwanz", progress = "NICHTS IST SCHLIMMER ALS DIESE BLAUEN ZIEGEN! ICH MEINE, WAS SOLLEN DIE ÜBERHAUPT DARSTELLEN?", completion = "EIN SCHWANZ! DAS WÄRE DOCH NICHT NÖTIG GEWESEN! DEN WERDE ICH STETS IN EHREN HALTEN!" }
quests[36042] = { id = 36042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menschliche Knochensplitter", progress = "MENSCHEN! UGH, DIE PLAGE VON AZEROTH! ES GIBT EINFACH SO VIELE VON IHNEN... DAS MACHT MICH SOOO WÜTEND!", completion = "GUTE ARBEIT. BRINGT MIR NOCH MEHR DAVON, UND ICH BRAUE EUCH EINE TASSE MEINER BERÜHMTEN MENSCHENKNOCHENBRÜHE! HAHAH!" }
quests[36046] = { id = 36046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 078 - Telaar Defender Shield" }
quests[36047] = { id = 36047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwischt", description = "Wir haben Gardul genau dort, wo wir ihn haben wollen, Kommandant.\n\nIhr seid viel besser für einen Kampf gegen ihn gerüstet als ich. Beseitigt ihn, nehmt Euch die Formel von seiner Leiche und schnappt Euch so viele Fässer mit Gift, wie Ihr könnt.\n\nIch werde diese Rampe bewachen und dafür sorgen, dass ihm keine Verstärkung zu Hilfe kommt.", sourceObjective = "Besorgt Giftdolchs Geheimformel und 6 Giftfässer.", progress = "Haben wir alles, was wir brauchen?", completion = "Hervorragend. Ich habe ein Reittier, das Euch zu Eurem Außenposten zurückbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36048] = { id = 36048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwischt", description = "Wir haben Gardul in die Enge getrieben, Kommandant.\n\nIhr habt eine viel bessere Chance gegen ihn als ich. Erledigt ihn und schnappt Euch die Formel von seiner Leiche und so viele Giftfässer, wie Ihr tragen könnt.\n\nIch bleibe hier und passe auf, dass Gardul keine Verstärkung erhält.", sourceObjective = "Besorgt Giftdolchs Geheimformel und 6 Giftfässer.", progress = "Ich will mich hier nicht länger aufhalten als nötig.", completion = "Perfekt. Ich hätte ein Reittier zu Eurem Außenposten für Euch, wenn Ihr so weit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[36049] = { id = 36049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 079 - Ogre Beads" }
quests[36050] = { id = 36050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 028 - Adventurer's Pouch" }
quests[36051] = { id = 36051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 035 - Grizzlemaw's Favorite Bone" }
quests[36052] = { id = 36052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 037 - Misplaced Artifacts" }
quests[36054] = { id = 36054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Gold", progress = "Gold ist in der Tat ein Schatz, aber zusätzliche Schätze für Gold? Das ist das Angebot, das ich Euch unterbreite. Ein Siegel des geschmiedeten Schicksals verzerrt die Zeit und bringt so im rechten Augenblick einen Schub zusätzlichen Glücks.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel des geschmiedeten Schicksals erwerben. Dieses hier zählt dazu. Nächste Woche habe ich vielleicht andere im Angebot.", completion = "Ein einfacher Austausch mit vielschichtigen Ergebnissen. Das ist die Kunst des Geschäftemachens." }
quests[36055] = { id = 36055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Apexiskristalle", progress = "Ihr scheint mir jemand zu sein, der stets nach Macht strebt, oder nicht? Diese Siegel sind sozusagen eine Investition in Eure zukünftige Macht.\n\nAuch ich bin machthungrig, aber ich suche nach einer Macht, die unmittelbarer und greifbarer ist. Wenn Ihr ein paar Kristalle findet, könnten wir einen Handel abschließen.\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich vielleicht andere im Angebot.", completion = "Ich wusste, wir verstehen uns." }
quests[36056] = { id = 36056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Garnisonsressourcen", progress = "Diese außergewöhnliche Befestigung, die Ihr da gebaut habt, ist beeindruckend. Sagt, hält sie all das Böse fern? Ja? Wie sähe es mit einem Tausch gegen ein wenig Glück aus? Eine Mauer kann dick genug sein, aber Glück kann man niemals genug haben. Außerdem... Sicherheit kann so kostspielig sein...\n\nDenkt daran, dass Ihr nur drei Siegel pro Woche erhalten könnt. Dies zählt als eines dieser drei. Nächste Woche werde ich vielleicht andere haben.", completion = "Fühlt Ihr Euch sicher, Fremder?" }
quests[36057] = { id = 36057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal besiegeln: Ehre", progress = "Jemand anderen für Ehre zu töten ist merkwürdig... ein Überbleibsel einer alten Zeit vielleicht? Wie dem auch sei, ich habe für dieses Siegel keine Verwendung. Es ist viel zu sehr mit Macht beladen, als dass ich es kontrollieren könnte..\n\nDenkt daran, Ihr könnt pro Woche nur drei Siegel erwerben. Dieses hier zählt dazu. Nächste Woche habe ich vielleicht andere im Angebot.", completion = "Ein allzu blutiger Preis dafür, das Glück auf seiner Seite zu haben. Hoffen wir, dass es das wert war." }
quests[36058] = { id = 36058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des geschmiedeten Schicksals: Arsenal" }
quests[36059] = { id = 36059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiges Gefäß", sourceObjective = "Erweckt den Klauenkönig.", completion = "Ihr kämpft gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[36062] = { id = 36062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kimzee Quetschpfeife", sourceObjective = "Also, ich habe nachgedacht.\n\nJetzt, da Onkel Krixel wieder da ist, kann ich mir eine Weile von der Werkstatt freinehmen.\n\nWenn Ihr in Eurer Garnison Platz habt, würde ich mich Euch gern anschließen und könnte Euch sogar ein paar Tricks beibringen. Ich kann Eure Konten ordentlich führen und die Bücher nett frisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[36063] = { id = 36063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
quests[36064] = { id = 36064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Artefaktfragmente", sourceObjective = "Es muss sehr viel Mühe gekostet haben, zu uns zurückzukehren. Sobald wir genügend Artefakte gesammelt haben, beschwören wir die Magierportale zurück zum Kriegsspeer in Ashran.", sourceObjectiveStatus = "unverified-source-field" }
quests[36065] = { id = 36065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine MENGE Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Es muss sehr viel Mühe gekostet haben, zu uns zurückzukehren. Sobald wir genügend Artefakte gesammelt haben, beschwören wir die Magierportale zurück zum Kriegsspeer in Ashran." }
quests[36066] = { id = 36066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Artefaktfragmente", progress = "Jedes bisschen zählt.", completion = "Jedes bisschen hilft." }
