quests[36074] = { id = 36074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 058 - Gambler's Purse" }
quests[36075] = { id = 36075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Ogronhorn", description = "Dieses Horn ist Beweis Eurer Stärke im Töten von Ogron, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt das Horn zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Kaum zu glauben, dass es noch brutalere Kreaturen als Oger gibt, aber auf Ogron trifft das zu. In der Arena einem gefangenen Ogron entgegenzutreten, ist keine einfache Aufgabe. Einem in seinem eigenen Versteck entgegenzutreten, ist sogar noch gefährlicher. Euch gebühren Ruhm und Ehre, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[36076] = { id = 36076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Ogronhorn", description = "Dieses Horn ist ein Beweis für Eure Fähigkeit im Töten von Ogron, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt das Horn zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Es gibt eine Kreatur, die noch brutaler als ein Oger ist. In der Arena einem gefangenen Ogron entgegenzutreten, ist keine einfache Aufgabe. Einem in seinem eigenen Versteck entgegenzutreten, ist sogar noch gefährlicher. Ich mag Euren Stil.", sourceObjectiveStatus = "unverified-source-field" }
quests[36077] = { id = 36077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 063 - Adventurer's Mace" }
quests[36078] = { id = 36078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gronnlingschuppe", description = "Diese Schuppe ist ein Beweis für Eure Stärke im Töten von Ogron, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Schuppe zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ein Gladiator sah Euch das vom Rücken eines Gronnling reißen, der sich bestimmt nicht leicht davon getrennt hat. Sie wirkt eher wie ein Stein als wie eine echte Schuppe, als würden diese Scheusale zum Teil aus Stein bestehen. Eine solche Trophäe ist nicht leicht zu bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36079] = { id = 36079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heldenempfang", description = "Ihr habt den Frostfeuergrat erreicht. Scharfseher Drek'Thar kann Euch von hier an führen.", sourceObjective = "Sprecht mit Scharfseher Drek'Thar an der Gletscherbucht im Frostfeuergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[36080] = { id = 36080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gronnlingschuppe", description = "Diese Schuppe ist ein Beweis für Eure Stärke im Töten von Ogron, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Schuppe zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ein Gladiator sah Euch das vom Rücken eines Gronnling reißen, der sich bestimmt nicht leicht davon getrennt hat. Sie wirkt eher wie ein Stein als wie eine echte Schuppe, als würden diese Scheusale zum Teil aus Stein bestehen. Eine solche Trophäe ist nicht leicht zu bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36081] = { id = 36081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gronnauge", description = "Dieses Auge ist ein Beweis für Eure Stärke im Töten von Gronn, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt das Auge zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ein Auge lässt sich kein lebender Gronn fortnehmen. Euer Gladiator hat einen schwer erkämpften Sieg beschrieben, und diese Trophäe legt Zeugnis von Euren Fähigkeiten ab. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[36082] = { id = 36082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 068 - Lost Pendant" }
quests[36083] = { id = 36083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Gronnauge", description = "Dieses Auge ist ein Beweis für Eure Stärke im Töten von Gronn, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt das Auge zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ein Auge lässt sich kein lebender Gronn fortnehmen. Euer Gladiator hat einen schwer erkämpften Sieg beschrieben, und diese Trophäe legt Zeugnis von Euren Fähigkeiten ab. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[36084] = { id = 36084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Botaniblüte", description = "Diese Blüte ist Beweis für Eure Stärke im Töten von Botani, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Blüte zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Mit den Botani ist nicht zu spaßen. Sie sind überaus gerissen, und ihre Kräfte sind auf ihrem Heimatboden immens. Sich eine ihrer Blüten zu nehmen, ist ein echter Beweis für Eure Kampfkünste!", sourceObjectiveStatus = "unverified-source-field" }
quests[36085] = { id = 36085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf schwarzen Schwingen", description = "Jetzt werden wir es den Jüngern zeigen. Raastok ist sich sicher, dass wir mit seiner jüngsten Erfindung die Apexiswaffen unter Kontrolle bekommen. Aber dafür müssen wir nah heran – verdammt nah.\n\nKa'alu und ihre Raben werden uns zur Windgepeitschten Terrasse fliegen. Dort müssen wir zuerst einen Brückenkopf sichern, bevor wir zur Morgenterrasse vorstoßen.", sourceObjective = "Erledigt 8 Jünger und Windbewahrer Koreyx. Sprecht wegen des Transports zur Windgepeitschten Terrasse mit Ka'alu.", progress = "Beeilung, wir dürfen uns diese Gelegenheit nicht entgehen lassen.", completion = "Gute Arbeit!\n\nJetzt wird es Zeit für die nächste Phase unseres Plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[36086] = { id = 36086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Botaniblüte", description = "Diese Blüte ist Beweis für Eure Stärke im Töten von Botani, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Blüte zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Mit den Botani ist nicht zu spaßen. Sie sind überaus gerissen, und ihre Kräfte sind auf ihrem Heimatboden immens. Sich eine ihrer Blüten zu nehmen, ist ein echter Beweis für Eure Kampfkünste!", sourceObjectiveStatus = "unverified-source-field" }
quests[36088] = { id = 36088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 068 - Beutel eines Abenteurers" }
quests[36089] = { id = 36089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 070 - Abu'gars Spule" }
quests[36090] = { id = 36090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Orcdorn", description = "Dieser Dorn ist Beweis für Eure Stärke beim Ausrotten der Befallenen. Und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Dorn zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Die Befallenen scheinen nur noch leere Hüllen zu sein, die durch die Kontrolle der Pflanzen am Leben gehalten werden. Sie sind langsam, aber sehr stark. Auch nur einen von ihnen zu besiegen, ist ein eindrucksvoller Beweis Eures Könnens!", sourceObjectiveStatus = "unverified-source-field" }
quests[36091] = { id = 36091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Orcdorn", description = "Dieser Dorn ist Beweis für Eure Stärke beim Ausrotten der Befallenen. Und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Dorn zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Manchmal werden wir nicht einfach nur in Pflanzenmulch verwandelt. Manchmal stehen wir wieder auf – randvoll mit Pflanzen. Die Befallenen sind schwer zu töten. Auch nur einen von ihnen zu besiegen, ist ein eindrucksvoller Beweis Eures Könnens!", sourceObjectiveStatus = "unverified-source-field" }
quests[36092] = { id = 36092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Ast eines Urtums", description = "Dieser Ast ist Beweis für Eure Stärke im Töten von Urtumen, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Ast zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Bei den Urtumen hier handelt es sich meist um Wächter und Hüter, aber das macht sie nicht weniger gefährlich. Ein wutentbranntes Urtum ist ein einschüchternder Anblick. Ihm einen Ast wegzunehmen, ist eine kühne Tat!", sourceObjectiveStatus = "unverified-source-field" }
quests[36094] = { id = 36094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Ast eines Urtums", description = "Dieser Ast ist Beweis für Eure Stärke im Töten von Urtumen, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Ast zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Bei den Urtumen hier handelt es sich meist um Wächter und Hüter, aber das macht sie nicht weniger gefährlich. Ein wutentbranntes Urtum ist ein einschüchternder Anblick. Ihm einen Ast wegzunehmen, ist eine kühne Tat!", sourceObjectiveStatus = "unverified-source-field" }
quests[36095] = { id = 36095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuka Klingenwut", description = "Agent Springschnell ist tot. Ein Feuer lodert tief in einer großen Wunde, direkt dort, wo einmal sein Herz war.\n\nNach dem Durchblättern eines Berichts, den Ihr bei seinem Leichnam gefunden habt, könnt Ihr Euch einige grundlegende Informationen zusammenreimen. Azuka hat die Oger betrogen, sie hat Ugbrecht getötet und seine Macht für sich selbst beansprucht.\n\nIhr solltet Bodrick diese Informationen sofort überbringen.", sourceObjective = "Kehrt zu Bodrick Grau in Eurer Garnison im Schattenmondtal zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[36096] = { id = 36096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Verheererklaue", description = "Diese Klaue ist Beweis für Eure Stärke im Töten von Verheerern, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Klaue zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Selbst die Insekten von Gorgrond sind größer und gemeiner als in anderen Teilen der Welt, die ich kenne! Sie zu töten, was Ihr offensichtlich getan habt, erfordert große Stärke und großes Können.", sourceObjectiveStatus = "unverified-source-field" }
quests[36097] = { id = 36097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Verheererklaue", description = "Diese Klaue ist Beweis für Eure Stärke im Töten von Verheerern, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Klaue zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Selbst die Insekten von Gorgrond sind größer und gemeiner als in anderen Teilen der Welt, die ich kenne! Sie zu töten, was Ihr offensichtlich getan habt, erfordert große Stärke und großes Können.", sourceObjectiveStatus = "unverified-source-field" }
quests[36098] = { id = 36098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Wespenstachel", description = "Dieser Stachel ist Beweis für Eure Stärke im Töten von Wespen, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Stachel zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Wie Ihr sehen könnt, ist das Gift der Wespen in Gorgrond überaus stark. Wer eine konfrontiert, riskiert damit den eigenen Tod. Ich würde davon abraten, mehr davon zu sammeln: einer reicht, um Eure Stärke zu beweisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36099] = { id = 36099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 046 - Goblinfass" }
quests[36100] = { id = 36100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksgebäude", description = "Ich sehe, dass Ihr die Pläne für ein Handwerksgebäude erworben habt! Nutzt den Architektentisch, um es auf einem kleinen Bauplatz zu errichten.", sourceObjective = "Errichtet ein beliebiges Handwerksgebäude.", completion = "Herzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[36101] = { id = 36101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Wespenstachel", description = "Dieser Stachel ist Beweis für Eure Stärke im Töten von Wespen, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Stachel zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Wie Ihr sehen könnt, ist das Gift der Wespen in Gorgrond überaus stark. Wer eine konfrontiert, riskiert damit den eigenen Tod. Ich würde davon abraten, mehr davon zu sammeln: einer reicht, um Eure Stärke zu beweisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36102] = { id = 36102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 045 - Saberonvorräte" }
quests[36103] = { id = 36103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Basiliskenschuppe", description = "Diese Schuppe ist ein Beweis für Eure Stärke im Töten von Basilisken, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Schuppe zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Eine schauerliche Trophäe von einer schauerlichen Bestie. Zum Erstarren gebracht und langsam gefressen zu werden, ist kein Tod, den ich mir aussuchen würde. Mit weniger Basilisken ist die Welt ein besserer Ort!", sourceObjectiveStatus = "unverified-source-field" }
quests[36104] = { id = 36104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Basiliskenschuppe", description = "Diese Schuppe ist ein Beweis für Eure Stärke im Töten von Basilisken, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt die Schuppe zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Eine schauerliche Trophäe von einer schauerlichen Bestie. Zum Erstarren gebracht und langsam gefressen zu werden, ist kein Tod, den ich mir aussuchen würde. Mit weniger Basilisken ist die Welt ein besserer Ort!", sourceObjectiveStatus = "unverified-source-field" }
quests[36105] = { id = 36105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Elementarkristall", description = "Dieser Kristall ist Beweis für Eure Stärke im Töten von Elementaren, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Kristall zu Jonaa und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Rangari Jonaa am Hochpass in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich habe nirgendwo sonst in Draenor Elementare gesehen, die es an Wildheit mit denen in Gorgrond aufnehmen könnten. Was sie wohl so wütend gemacht hat? Ich bin sicher, dieser Kristall ist schwer erkämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[36106] = { id = 36106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkebeweis: Elementarkristall", description = "Dieser Kristall ist Beweis für Eure Stärke im Töten von Elementaren, und Euer Gladiatorfreund kann es bezeugen!\n\nBringt den Kristall zu Schinder und nehmt Eure Anerkennung entgegen!", sourceObjective = "Bringt den Beweis zu Schinder an der Wildwacht in Gorgrond.\n\nBereitgestellter Gegenstand:", completion = "Ich habe nirgendwo sonst in Draenor Elementare gesehen, die es an Wildheit mit denen in Gorgrond aufnehmen könnten. Was sie wohl so wütend gemacht hat? Ich bin sicher, dieser Kristall ist schwer erkämpft!", sourceObjectiveStatus = "unverified-source-field" }
quests[36107] = { id = 36107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäenjäger von Gorgrond", sourceObjective = "Ich glaube, ich spreche für uns alle, wenn ich sage, dass Ihr zu den gefährlichsten Jägern von Gorgrond gehört! Ihr habt es mit den bedrohlichsten Kreaturen von Gorgrond auf ihrem eigenen Terrain aufgenommen und überlebt und dazu noch ein Andenken mitgebracht.\n\nDie Gladiatoren haben sich versammelt und etwas gefunden, was der Welt Eure Macht zeigt! Genießt den Ruhm, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[36108] = { id = 36108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäenjäger von Gorgrond", sourceObjective = "Ich glaube, ich spreche für uns alle, wenn ich sage, dass Ihr zu den gefährlichsten Jägern von Gorgrond gehört! Ihr habt es mit den bedrohlichsten Kreaturen von Gorgrond auf ihrem eigenen Terrain aufgenommen und überlebt und dazu noch ein Andenken mitgebracht.\n\nDie Gladiatoren haben sich versammelt und etwas gefunden, was der Welt Eure Macht zeigt! Genießt den Ruhm, Champion!", sourceObjectiveStatus = "unverified-source-field" }
quests[36109] = { id = 36109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 024 - Goldzehs Plündergut" }
quests[36111] = { id = 36111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Hause" }
quests[36112] = { id = 36112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Hause" }
quests[36115] = { id = 36115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 017 - Elixier der Fahlen" }
quests[36116] = { id = 36116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Schatz 061 -Beutel voller Kräuter" }
quests[36117] = { id = 36117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Zerschlagene Anhöhe", description = "Ihr da! Ihr seid hier der Kommandant, stimmt's? Ich vertrete die Interessen der Werterhaltungsgesellschaft des Dampfdruckkartells.\n\nWir versuchen schon seit einer Weile, in Nagrand eine sehr wichtige Ausgrabung in Gange zu bringen. Leider machen uns die Oger in der Gegend etwas Schwierigkeiten.\n\nEiner unserer besten Werterhalter ist beim Vermessen des Gebiets sogar kürzlich verschwunden. Er ist schon der dritte, den wir diese Woche da oben verloren haben!\n\nWir sind nicht wirklich für eine Rettungsaktion ausgerüstet... wollt Ihr uns helfen? Wir könnten die Unterstützung wirklich gebrauchen.", sourceObjective = "Findet Greblin Flinkzünd.", completion = "Ihr sucht was? Ich meine, ja, klar... schon in Ordnung. Holt mich einfach nur runter, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[36118] = { id = 36118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Geröllhaufen" }
quests[36119] = { id = 36119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Ashran", description = "Seid gegrüßt und willkommen in Ashran. Meldet Euch bei Kommandantin Anne Dunworthy beim Sturmschild, um Eure Anweisungen zu erhalten.", sourceObjective = "Sprecht mit Kommandantin Anne Dunworthy beim Sturmschild.", sourceObjectiveStatus = "unverified-source-field" }
quests[36123] = { id = 36123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Wildnis", description = "Die Straße des Ruhms ist in diesem Land nicht das einzig umkämpfte Gebiet, {name}. Wir müssen die Artefakte in der Wildnis suchen.\n\nGeht und tötet in den Außenbezirken ein Mitglied der Horde und bringt mir einen Teil der Rüstung von der Leiche mit. Damit könnt Ihr mir beweisen, was Ihr wert seid.", sourceObjective = "Chris Clarkie in der Sturmschildfeste will, dass Ihr ein Mitglied der Horde abseits der Hauptstraße tötet und ein Stück seiner Rüstung als Beweis mitbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36125] = { id = 36125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße des Ruhms", description = "Die Horde will uns aus Ashran drängen, {name}. Das dürfen wir nicht zulassen. Marschiert zur Straße des Ruhms und vernichtet mindestens fünf von ihnen.", sourceObjective = "Chris Clarkie beim Sturmschild will, dass Ihr 5 Mitglieder der Horde auf der Straße des Ruhms tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[36127] = { id = 36127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundet Ashran", description = "Als Scharfseherin kann ich vom Sturmschild aus noch in die fernsten Winkel Ashrans sehen. Ihr jedoch müsst losziehen, um es mit eigenen Augen zu sehen, {name}.", sourceObjective = "Scharfseherin Kylanda am Sturmschild will, dass Ihr in Ashran Folgendes erkundet: die Straße des Ruhms, den Geschmolzenen Steinbruch, das Schlägerplateau, das Amphitheater der Auslöschung und den Friedhof der Aschehämmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[36128] = { id = 36128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säbelschlund - Saberon Vignette Boss" }
quests[36129] = { id = 36129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nas Dunberlinn" }
quests[36130] = { id = 36130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzbereit", description = "Strammstehen, {name}! Wir haben keine Zeit zu verlieren. Sprecht mit meinen Leuten hier, sie werden Euch in alles Wichtige einweisen.", sourceObjective = "Sprecht mit Misirin Starkzeh, Scharfseherin Kylanda und Chris Clarkie.", sourceObjectiveStatus = "unverified-source-field" }
quests[36131] = { id = 36131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Als Krieger habt Ihr gezeigt, was Ihr könnt. Sehen wir doch mal, wie es um Eure Angelkenntnisse bestellt ist. Ich habe einen Köder aus den Eisstachelstechern gebastelt, die Ihr mir gebracht habt. Angelt damit in diesem Küstengewässer nach Zangaraalen.", sourceObjective = "Beweist Mokugg Hauwech Euer Talent, indem Ihr mit seinem Köder 5 Zangaraale fangt.", progress = "Schon Aale gefangen?", completion = "Ich sehe, nicht nur das Kriegshandwerk, auch das Angeln liegt Euch. Ich werde tun, was ich kann, um Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36132] = { id = 36132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln in unserer Garnison", description = "Ihr habt Euren Wert bewiesen, <Reisender/Reisende>. Jetzt nehmt das Anglertagebuch der Frostwölfe in Eure Garnison mit und studiert es aufmerksam. Dann werdet Ihr schon bald mehr fangen, als Ihr essen könnt.", sourceObjective = "Kehrt mit dem Anglertagebuch der Frostwölfe zu Mak'jin zurück.", progress = "Das können wir als Köder verwenden?!", completion = "Seht Euch nur all die Ideen für Köder in diesem Ding an! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[36133] = { id = 36133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdeckung der Artefaktfragmente", description = "Die Artefaktfragmente scheinen von Kreaturen zu stammen, die wir in den Außenbezirken von Ashran gefunden haben. Geht und tötet alle, die Ihr findet, und bringt mindestens fünf zu Ecilam dem Magier am Lagerfeuer in der Sturmschildfeste.", sourceObjective = "Misirin Starkzeh in der Sturmschildfeste möchte, dass Ihr Kreaturen in den Außenbezirken von Ashran abseits der Hauptstraße tötet und 5 Artefaktfragmente zu Ecilam bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36134] = { id = 36134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Erwachen", description = "Wir haben Kriegsfürstin Klingenwut und das gestohlene Artefakt in den Salzfeldern im Westen Gorgronds ausfindig gemacht.\n\nThisalee Krähe wird sich dort mit Euch treffen. Sie hat einen Spähtrupp dabei.\n\nDie gesamte Garnison wurde in höchste Alarmbereitschaft versetzt. Wir müssen bereit sein, den Feind aufzuhalten, falls es nötig wird.", sourceObjective = "Sprecht mit Thisalee Krähe in Gorgoreks Ruh in Gorgrond.", completion = "Ich habe noch nie einen Magnaron von dieser Größe gesehen. Das ist wirklich übel, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36136] = { id = 36136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Erwachen", description = "Wir hab'n Kriegsfürstin Klingenwut und das gestohl'ne Titanenartefakt im Norden von Gorgrond entdeckt.\n\nCholuna is' auch schon da, mit 'nem Spähtrupp.\n\nIch hab schon ma' die ganze Garnison hier flottgemacht. Trefft Euch mit ihr und fangt den Feind ab, falls nötig.", sourceObjective = "Sprecht mit Choluna in Gorgoreks Ruh in Gorgrond.", completion = "Ich habe noch nie einen Magnaron von dieser Größe gesehen. Das ist wirklich übel, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36137] = { id = 36137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichter Einstieg in die Holzfällerei", description = "Wir werden viel Holz brauchen, wenn wir diese Garnison zu einer geeigneten Festung ausbauen wollen. Das heißt, wir haben alle Hände voll zu tun.\n\nIch würde Euch nie bitten, Euch die Hände mit gewöhnlicher Arbeit schmutzig zu machen, aber Ihr müsst nach Holz für unser Sägewerk suchen. Sobald Ihr einen Baum markiert habt, wird irgendein kräftiger, fauler, nichtsnutziger Peon ihn fällen und Euch das Holz geben.\n\nFrostfeuer ist nicht der beste Ort für Bauholz, aber immerhin habe ich in der Nähe einen passenden kleinen Baum gesehen.", sourceObjective = "Besorgt eine Holzprobe vom kleinen Baum und bringt sie zu Holzherr Oktron.", progress = "Diese Garnison wird sich nicht von selbst bauen, Kommandant! Wir brauchen Holz!", completion = "Ihr werdet einen guten Aufseher abgeben! Die Peons müssen spuren!\n\nJetzt wisst Ihr das Wichtigste darüber, wie man Holz findet und Bäume fällt. Es wird Zeit, all das zum Nutzen Eurer Garnison anzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36138] = { id = 36138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Holz Kohle machen", description = "Jetzt, da Ihr wisst, wie man die Peons für die Holzernte an die Arbeit schickt, können wir einen Arbeitsauftrag für Euer Sägewerk erstellen.\n\nDoch zunächst brauchen wir Holz, das wir verarbeiten können!\n\nÜberall in Draenor gibt es saftige Bäume, die zum Fällen reif sind. Geht hinaus und findet passendes Holz für das Sägewerk. Kommt hierher zurück, wenn Ihr genug habt und wir beginnen mit einem Arbeitsauftrag.\n\nUnd lasst wie immer die Peons die harte Arbeit tun. Ihr müsst sie nur beschützen. Draenor ist ein gefährlicher Ort!", sourceObjective = "Sammelt 10 Stücke Holz in ganz Draenor und erteilt dann dem Sägewerk Eurer Garnison einen Arbeitsauftrag.", completion = "So ist es genau richtig, Kommandant!\n\nWir haben jetzt alles, um in Betrieb zu gehen. Kommt einfach zu mir, wenn Ihr genug Holz für einen Arbeitsauftrag habt und wir mit der Arbeit beginnen können.\n\nDiese Garnison baut sich schließlich nicht von selbst auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[36139] = { id = 36139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Pandaria - Dungeon Normal Nth" }
quests[36140] = { id = 36140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaria 88-90" }
quests[36141] = { id = 36141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisstachelstecher", description = "Ich werde Euch helfen, aber Ihr müsst mir beweisen, dass Ihr nicht nur gut angeln könnt, sondern auch <ein furchtloser Krieger/eine furchtlose Kriegerin> seid.\n\nDie Schlucht nördlich von uns ist voller Eisstachelstecher. Erledigt sie und bringt mir ihre Stacheln. Die dürften in diesen Gewässern einen guten Köder abgeben.", sourceObjective = "Beweist Mokugg Hauwech Euer Talent, indem Ihr 4 Eisstachelstecher sammelt.", progress = "Habt Ihr die Stacheln für mich?", completion = "Nicht schlecht, Reisender, gar nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36142] = { id = 36142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schärfere Klingen, größere Bäume", description = "Unglaubliche Neuigkeiten, Kommandant {name}. Euer ergebenster Diener (das bin ich) hat es geschafft, uns Holzherren zu verschaffen. Jetzt wisst Ihr vielleicht nicht, was ein Holzherr ist, also erkläre ich es Euch: Stellt Euch einen blutgierigen Massenmörder vor, der nichts lieber tut, als zu töten. Jetzt nehmt Ihr diese Begeisterung fürs Töten und übertragt sie auf das Töten von Bäumen! Das ist ein Holzherr!\n\nDas bedeutet, dass wir nun mittelgroße Bäume fällen können, doch müssen wir zunächst diese Holzherren auf die Probe stellen.\n\nIn der Nähe steht ein passender Baum. Viel Glück!", sourceObjective = "Sammelt eine Holzprobe und bringt sie zu Holzherr Oktron.", progress = "Habt Ihr die Holzprobe schon?", completion = "Ihr wolltet mir bezüglich dieser Holzherren nicht glauben, oder? Nun, jetzt wisst Ihr Bescheid.\n\nSieht aus, als würde diese Gruppe Euch in Zukunft gute Dienste leisten, Kommandant. Mittelgroße Bäume überall in Draenor sind jetzt Eurer Gnade ausgeliefert. Das heißt, es gibt pro Baum mehr Holz!", sourceObjectiveStatus = "unverified-source-field" }
quests[36143] = { id = 36143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Lich King - Dungeon Normal 1st" }
