quests[36152] = { id = 36152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm 84-85" }
quests[36157] = { id = 36157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme des Verräters", description = "Ich muss Euch um einiges bitten, {name}, aber bevor wir anfangen, muss ich sicherstellen, dass Ihr Euer volles Potenzial entwickelt. Ich kann Euch da helfen.\n\nIch würde gern eine Verbindung zwischen uns erschaffen, ein Artefakt, das Eure Macht verstärkt und es mir ermöglicht, Euren Fortschritt zu verfolgen. Was haltet Ihr von Amuletten? Nein? Einem Ring? Ich hab's.\n\nMeine Kontakte unter den ausgestoßenen Arakkoa erzählen mir von einem Ring aus reinem Solium. Im Moment hat ihn die oberste Weise Viryx hoch auf der Himmelsnadel in den Klauen. Bringt mir den Ring, {name} – wir beide werden ihn viel besser einzusetzen wissen.", sourceObjective = "Besorgt ein Band aus reinem Solium von der Obersten Weisen Viryx in der Himmelsnadel.", progress = "Die Arakkoa sind heute nur noch ein Schatten ihrer früheren Herrlichkeit. Sie verstecken sich auf ihren Türmen und blicken finster auf das Land darunter, eingebildet und überheblich. In Wahrheit sind sie von eben den Feinden auf ihre luftigen Sitze getrieben worden, auf die sie heute herabblicken.\n\nIch wünschte, mit den Arakkoa wäre leichter auszukommen. Ihre Manipulation der Sonnenstrahlen hätte uns viel Nutzen bringen können.", completion = "Der Ring! Ihr habt ihn. Merkt Ihr, dass er sich immer noch warm anfühlt? In das Metall ist die Macht der Sonne von Draenor eingeschlossen. Das ist perfekt, {name}. Genau das Grundmaterial, das wir brauchen, um daraus etwas Fantastisches zu machen.\n\nReden wir über unsere nächsten Schritte, während ich Euren Schatz präpariere...", sourceObjectiveStatus = "unverified-source-field" }
quests[36158] = { id = 36158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenors geheime Macht", description = "Da wir so eng zusammenarbeiten werden, möchte ich Euren Ring aufwerten. Uralte Magie ist der Schlüssel: Apexiskristalle, die Überbleibsel einer früheren Arakkoazivilisation! Sie sind unter den gefährlichsten Kreaturen der ganzen Welt zu finden.\n\nSammelt 4986 Kristalle für mich.\n\nSeht mich nicht so an. Ich bin ein Magier. Ich kenne die Zahlen. Ich brauche genau 4986 Kristalle. 4985 sind zu wenig. 4987 sind natürlich absurd.\n\nViertausendneunhundertsechsundachtzig. Geht!", sourceObjective = "Sammelt 4986 Apexiskristalle für Erzmagier Khadgar. Kristalle sind bei den Kreaturen in den gefährlichsten Gegenden der Welt zu finden.", progress = "Habt Ihr die Kristalle? Ich hoffe, Ihr habt genau mitgezählt. Wenn Ihr Euch verzählt habt, kann ich nicht dafür garantieren, was passiert.", completion = "Wunderbar, wunderbar! Die werde ich dazu verwenden, Euren Ring aufzuwerten, wenn wir noch ein paar Aufgaben erledigt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[36159] = { id = 36159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 004 - Schotterzahn" }
quests[36160] = { id = 36160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Jede Rose hat einen Dorn", description = "Meine Gefühle sind einfach zu stark. Ich kann meine Liebe nicht länger verbergen.\n\nIch muss Dorn die Wahrheit sagen. Ich muss ihr sagen, wie sehr ich sie liebe.\n\nSie hat erwähnt, dass Rosen ihre Lieblingsblumen sind. Ich war so in meine Arbeit vertieft... Ich weiß nicht einmal, wo in Draenor Rosen wachsen.", sourceObjective = "Besorgt Baros eine Rose für Dorn.", progress = "Wir werden angegriffen!", completion = "Kommandant! Wir wurden gerade von der Brennenden Klinge angegriffen. Sie befinden sich auf der Suche nach dem Herz von Gorgorek.\n\nZum Glück war Leutnant Dorn zur Stelle und hat uns beschützt.\n\nWas? Ihr habt eine Rose gefunden? Psst, gebt sie mir, schnell. Ich werde sie aufbewahren, bis der rechte Zeitpunkt gekommen ist, meine Liebe zu gestehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36161] = { id = 36161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Rauch ist...", description = "Assassinen der Brennenden Klinge sind in die Garnison eingedrungen. Kommandant, wir dürfen nicht zulassen, dass sie das Herz von Gorgorek in ihre Finger bekommen!", sourceObjective = "Tötet Rag'sla Dumpfklinge, Akatha Feuerlohe und Drek den Feuerrufer.", completion = "Die Assassinen tauchten aus dem Nichts auf...\n\nBaros warf sich vor die Klinge, die für mein Herz bestimmt war. Ich riss dem Angreifer die Kehle auf... doch es war zu spät.\n\nBevor er starb, gab mir Baros diese Rose.\n\n<Dorn hält die Rose hoch. Eine Träne kullert ihre Wange herunter.>", sourceObjectiveStatus = "unverified-source-field" }
quests[36162] = { id = 36162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gestohlenes Herz", description = "Lasst nicht zu, dass Azuka das Herz bekommt, Kommandant. Lasst sie nicht gewinnen.", sourceObjective = "Tötet Azuka Klingenwut.", completion = "Heute war kein guter Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[36163] = { id = 36163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Ruf der Exarchin", description = "Ah, {race}, genau auf jemanden wie Euch hatte ich gehofft.\n\nYrel war vorhin in der Garnison und hat nach Euch gefragt. Was für ein nettes Mädchen! Hat nach meiner Familie gefragt, gerade jetzt, wo ich Heimweh habe. Wie nett von ihr. Aber was wollte ich eigentlich sagen?\n\nAch, ja! Sie hat darum gebeten, dass Ihr sie in Elodor, im Osten, trefft.\n\nSie ist zu einem Draeneirat eingeladen worden, um die Exarchenprüfungen abzulegen – was immer das sein mag.\n\nAlso solltet Ihr gleich aufbrechen!", sourceObjective = "Sprecht mit Yrel in Elodor im Schattenmondtal.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36164] = { id = 36164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Mutes", description = "Ein Exarch muss ein starker Fels in der Brandung sein, und nichts verleiht mehr Stärke, als der Mut, sich einer Gefahr zu stellen.\n\nWeit im Nordwesten, unter den schneebedeckten Felshängen des Frostfeuergrats, lebt ein Urzorn namens Immerflamme.\n\nNur, wenn Ihr einer solchen Kreatur Auge in Auge gegenübersteht, werdet Ihr wissen, wie viel Mut Ihr wirklich habt.", sourceObjective = "Tötet Immerflamme.", completion = "Ich sehe, dass Ihr und Yrel den urtümlichsten Elementaren in die Augen geschaut habt und dennoch nicht von Eurem Pfad abgewichen seid.\n\nEs freut mich, bestätigen zu können, dass es Euch nicht an Mut mangelt.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36165] = { id = 36165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit zu verlieren", description = "Wir haben Glück, Kommandant. Das Gegenmittel ist ziemlich einfach herzustellen.\n\nIch hab' eine kleine Menge mit dem Zeug gemacht, das ich bei mir hatte. Ihr solltet es zu Kolrigg bringen, bevor es zu spät ist. Es wird ihn lange genug am Leben halten, bis ich mehr fertig hab'.", sourceObjective = "Tragt die Salbe der Spitzen bei Kolrigg Stoktron in Südhafen auf.", completion = "Bei Muradins Bart... solche Kopfschmerzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36166] = { id = 36166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit zu verlieren", description = "Kommandant, wir haben Glück. Das Rezept für das Gegenmittel ist ziemlich einfach.\n\nIch habe eine kleine Menge mit dem gemacht, was ich bei mir hatte. Ihr solltet es zu Lunzul bringen, bevor es zu spät ist. Es wird sie lange genug am Leben halten, bis ich mehr fertig habe.", sourceObjective = "Behandelt Lunzul in Axtfall mit der Salbe der Spitzen.", completion = "Bei den Geistern... mir brummt der Schädel...", sourceObjectiveStatus = "unverified-source-field" }
quests[36167] = { id = 36167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Herzens", description = "Die Prüfung des Herzens ist eine Prüfung Eurer Bereitschaft, auch im Angesicht einer großen Herausforderung zu bestehen.\n\nWeit im Westen, an der Himmelblauen Lagune, gibt es einen Rangariaußenposten.\n\nSie haben von dort um Unterstützung gebeten. Irgendeine Art Infektion lässt alle Leute in dieser Gegend erkranken. Sie brauchen dringend Hilfe.\n\nBegebt Euch dorthin und sucht die Rangari auf. Helft ihnen, die Ursache für diese fürchterliche Krankheit zu finden.", sourceObjective = "Sprecht mit Yrel an der Himmelblauen Lagune und findet die Ursache für den Giftnebel heraus.", completion = "Der Ruf Eurer erstaunlichen Taten eilt Euch voraus. Rangari Saardar hat bereits von Eurer ausgezeichneten Arbeit berichtet.\n\nIch danke Euch beiden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36168] = { id = 36168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Vertrauens", description = "Zu jeder Exarchenprüfung gehört eine heilige Pilgerreise zur Grabstelle unserer gefallenen Champions.\n\nIch werde Euch die Asche von Verteidiger Maraad mit auf den Weg geben und möchte Euch bitten, sie in ihre letzte Ruhestatt, den heiligen Hallen von Auchindoun, zu bringen.\n\nDort werden dann die Geister unserer gefallenen Vorfahren Yrels größte Schwäche auf die Probe stellen.\n\nViel Glück.", sourceObjective = "Sprecht mit Seelenbinderin Tuulani vor dem Eingang nach Auchindoun und stellt Euch der Prüfung des Vertrauens.", completion = "Eure Reise scheint ein Erfolg gewesen zu sein.\n\nWundert Ihr Euch, wie ich das wissen kann? Nun, wenn Ihr die Prüfung der Vorfahren nicht bestanden hättet, wäret Ihr gar nicht mehr zurückgekehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36169] = { id = 36169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Champions", description = "Ihr habt die ersten drei Prüfungen mit Leichtigkeit bestanden.\n\nIn der letzten Prüfung müsst Ihr Euch dem Exarchenrat stellen.\n\nSprecht mich an, wenn Ihr dazu bereit seid.", sourceObjective = "Besiegt den Exarchenrat.", completion = "Gut gemacht, Champion. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36170] = { id = 36170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Femur der Unwahrscheinlichkeit" }
quests[36171] = { id = 36171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Botani!", description = "Die Pflanzen sind heute irgendwie anders. Grashalme biegen sich entgegen der Windrichtung und wickeln sich um meine Stiefel. Heute Morgen sind mir dann noch zwei Äste auf den Helm gefallen.", sourceObjective = "Schlagt die Invasion Eurer Garnison durch die Botani zurück.\n\n(Sprecht erneut mit Unteroffizier Krähler, um zu beginnen.)", completion = "Wir haben die Natur besiegt, Kommandant. Würdet Ihr mich entschuldigen? Ich würde gern all diesen Pflanzensaft so schnell wie möglich aus meiner Rüstung entfernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36174] = { id = 36174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 081 - Bounty of the Elements" }
quests[36176] = { id = 36176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger gesucht", description = "<Die Notiz ist kaum lesbar, aber anscheinend handelt es sich um die Ankündigung eines lokalen Jagdwettbewerbs in der Nähe von Embaari.>\n\n\"Alle Interessierten sind herzlich eingeladen, ihr Können bei einem freundschaftlichen Jagdwettbewerb unter Beweis zu stellen.\"", sourceObjective = "Bringt die verdreckte Notiz zu Fanara in Embaari, um am Wettbewerb teilzunehmen.\n\nBereitgestellter Gegenstand:", completion = "Noch jemand für den Wettbewerb? Wunderbar! Garaal wird hocherfreut sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[36177] = { id = 36177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlicher Wettbewerb", description = "Ihr wollt also am Wettbewerb teilnehmen, {name}? Ich wünsche Euch viel Glück.\n\nBesorgt in der Wildnis einen Sack voll Häute und Klauen der einheimischen Wildtiere und bringt sie mir vor allen anderen Teilnehmern!\n\nDem Sieger winkt die Gelegenheit, Handwerker Garaals Lehrling zu werden.\n\nMöge der Beste gewinnen!", sourceObjective = "Sammelt 4 Bälge von Schattenmondwildtieren und 3 Silberschwingenklauen und bringt sie vor Euren Mitstreitern zu Fanara.", progress = "Der Ranzen ist voll und bereit für die Lieferung.", completion = "Glückwunsch, {name}! Ihr habt es geschafft!\n\nWeit und breit ist keiner der anderen Teilnehmer zu sehen!\n\nGaraal wird höchst zufrieden sein. Bei so vielen Arbeitsmaterialien werden er und die anderen Handwerker problemlos im Geschäft bleiben.\n\nIch werde die Häute sofort gerben, damit Ihr sie bald abliefern könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36178] = { id = 36178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mandrakor der Nachtjäger" }
quests[36179] = { id = 36179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unliebsame Plagegeister", description = "Diese Kreaturen draußen im Watt zerstören die Türme schneller, als wir sie wieder in Betrieb nehmen können.\n\nIch soll die Biester ausschalten, aber mein Flammenwerfer ist vollkommen kaputt. Mit dem verdammten Ding kann ich nicht mal eine Kerze anzünden!\n\nKönntet Ihr mir einen Gefallen tun und ein paar dieser Landplagen töten, während ich meinen Flammenwerfer zur Reparatur bringe?\n\nSagt nur Gazwitz Bescheid, dass Ihr für mich einspringt, damit ich die Reparatur ersetzt bekomme.", sourceObjective = "Tötet 10 Sporentreiber oder Funguskolosse in Sporennebelwatt.", completion = "Lemmys Waffe ist also mal wieder kaputt, ja?\n\nIhr habt ihn da draußen gut vertreten. Ich könnte mehr Arbeiter wie Euch brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36182] = { id = 36182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baum-o-zid", description = "Kommandant, die Goblins haben Euch ein Geschenk gemacht. Sie nennen es den \"Baummörder 9000\".\n\nWas man damit machen kann? Bäume ermorden, nehme ich an. Aber vor allem kann man damit große Mengen Bauholz ernten. Wisst Ihr, wie viel Bauholz man aus so einem großen Baum gewinnen kann? Ich auch nicht. Aber ich wette, es ist eine große Menge!\n\nGanz in der Nähe steht ein großer Baum, der darauf wartet, ermordet zu werden. Warum macht Ihr nicht mal einen Probedurchgang mit dem neuen Gerät? Bringt mir einfach zurück, was Ihr damit erarbeiten konntet. Ich werde sicher gute Verwendung dafür finden.", sourceObjective = "Besorgt eine Holzprobe von einem großen Baum und bringt sie zu Holzherr Oktron.", progress = "Habt Ihr schon die Holzprobe eingeholt?", completion = "Das ist ja fantastisch! Diese Probe deutet auf massive Bestände großer Bäume in ganz Draenor hin. Und mit Eurem neuen Baummörder 9000 könnt Ihr diese gewaltigen Baummonster blitzschnell kurz und klein sägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36183] = { id = 36183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor", description = "Admiral Taylor wusste, wer hinter all dem steckte. Er wies uns an, jeden zu retten, den wir retten können... Er wollte die Dinge selbst in die Hand nehmen.\n\nWir haben nie wieder von ihm gehört, aber wir haben unsere Befehle.\n\nBitte... findet ihn. Er ging in Richtung des Bauernhofs.", sourceObjective = "Findet Admiral Taylor auf Admiral Taylors Bauernhof.", completion = "Von Kommandant zu Kommandant... Danke.\n\nIn so vielen Schlachten standen wir uns gegenüber. Vashj'ir... der Jadewald... die Löwenlandung...\n\nIch bin froh, mein Ende durch solch einen würdigen Gegner zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36184] = { id = 36184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldgrube" }
quests[36185] = { id = 36185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechter Handel", description = "In Ordnung, bitte sehr!\n\nBringt sie schnell zu Garaal. Er hat ein großes Interesse an detailreichen und feinen Handwerksstücken. Er wird Eure Arbeit sicher zu schätzen wissen.", sourceObjective = "Garaal erwartet Eure Lieferung.\n\nBereitgestellter Gegenstand:", completion = "Seid gegrüßt, {name}.\n\nVon Fanara habe ich gehört, dass der Wettbewerb dieses Jahr sehr hart war.\n\nMeine Güte. Diese Materialien sollten für eine ganze Saison reichen!\n\nFür gewöhnlich wird der Sieger des Wettbewerbs mein neuer Lehrling, doch Ihr seid ganz offensichtlich schon weit über das Stadium eines Lehrlings hinaus.\n\nVielleicht kann ich Euch einen Handel vorschlagen.\n\nIch behalte Eure Lieferung und teile sie mit den anderen Handwerkern vor Ort. Im Gegenzug werde ich Euch etwas von unserem Wissen vermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[36186] = { id = 36186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Greldrok der Listige" }
quests[36189] = { id = 36189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichter Einstieg in die Holzfällerei", description = "Kommandant, wir werden viel Holz brauchen, wenn wir diese Garnison zu einer geeigneten Festung ausbauen wollen. Das heißt, wir haben alle Hände voll zu tun.\n\nIch würde Euch nie bitten, Euch die Hände mit gewöhnlicher Arbeit schmutzig zu machen, aber Ihr müsst nach Holz für unser Sägewerk suchen. Sobald Ihr einen Baum markiert habt, wird ein Holzfäller ihn fällen und Euch das Holz geben.\n\nGeben wir doch mal unseren Holzfällern eine Gelegenheit, sich zu beweisen. Da drüben ist schon ein Baum!", sourceObjective = "Besorgt eine Holzprobe von einem kleinen Baum und bringt sie zu Helge Holzschneider.", progress = "Diese Garnison wird sich nicht von selbst bauen, Kommandant! Wir brauchen Holz!", completion = "Ihr werdet einen guten Aufseher abgeben! Die Holzfäller müssen spuren!\n\nJetzt wisst Ihr das Wichtigste darüber, wie man Holz findet und Bäume fällt. Es wird Zeit, all das zum Nutzen Eurer Garnison anzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36192] = { id = 36192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Holz Kohle machen", description = "Ihr wisst jetzt, wie man die Holzfäller zur Arbeit schickt. Jetzt brauchen wir einen Arbeitsauftrag für Euer Sägewerk.\n\nAber dazu brauchen wir zunächst einmal etwas Holz!\n\nEs stehen überall in ganz Draenor fette Bäume herum, die nur darauf warten, gefällt zu werden. Zieht los und findet ein paar solcher Bäume für Euer Sägewerk. Kommt hierher zurück, wenn Ihr genug davon gefunden habt. Dann werden wir mit dem Arbeitsauftrag beginnen.\n\nUnd überlasst die harte Arbeit wie immer den Holzfällern. Gewährt ihnen einfach nur Schutz. Draenor ist ein gefährlicher Ort!", sourceObjective = "Sammelt 10 Stücke Holz in ganz Draenor und erteilt dann dem Sägewerk Eurer Garnison einen Arbeitsauftrag.", completion = "So ist es genau richtig, Kommandant!\n\nWir haben jetzt alles, um in Betrieb zu gehen. Kommt einfach zu mir, wenn Ihr genug Holz für einen Arbeitsauftrag habt und wir mit der Arbeit beginnen können.\n\nDiese Garnison baut sich schließlich nicht von selbst auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[36193] = { id = 36193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Akt der Barmherzigkeit", description = "Ich weiß, dass Ihr und Verteidigerin Yrel in dringender Angelegenheit hier seid, aber ich muss Euch dennoch um einen Gefallen bitten.\n\nEine Einheit Rangari hat sich auf Patrouille begeben, kurz bevor der Giftnebel auftauchte.\n\nWenn sie der Nebel im Sumpf überrascht hat, sind sie jetzt ganz sicher in Schwierigkeiten.\n\nSammelt bitte die regenerierenden Goldlinge im Schilf und verwendet sie, um alle gefallenen Rangari, die Ihr finden könnt, wiederzubeleben.\n\nUnd esst selbst einen davon, wenn Ihr Probleme bekommt und das Gift bekämpfen müsst.", sourceObjective = "Verwendet die regenerierenden Goldlinge, um die gefallenen Rangari wiederzubeleben.", completion = "Dem Licht sei Dank! Alle vermissten Rangari sind zurückgekehrt. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[36194] = { id = 36194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schärfere Klingen, größere Bäume", description = "Es gibt unglaubliche Neuigkeiten, Kommandant {name}. Eurem treu ergebenen Diener ist es gelungen, die Dienste von Kommandoholzfällern zu sichern. Solltet Ihr nicht wissen, was Kommandoholzfäller sind, werde ich es Euch erklären: Sie sind eine Art Holzfäller, nur viel besser ausgebildet im Töten. In den meisten Fällen handelt es sich um arbeitslose Söldner und Assassinen.\n\nDas bedeutet, dass wir von nun an mittelgroße Bäume fällen können. Aber zunächst sollten wir den Kommandoholzfällern eine Gelegenheit geben, sich zu beweisen.\n\nIch habe in der Nähe einen passenden Baum gesehen. Viel Glück!", sourceObjective = "Besorgt eine Holzprobe von einem mittelgroßen Baum und bringt sie zu Helge Holzschneider.", progress = "Habt Ihr schon die Holzprobe eingeholt?", completion = "Wir sind noch nicht annähernd in die Verlegenheit gekommen, zu viel abzuholzen.\n\nIch glaube, diese Gruppe wird Euch gute Dienste leisten, Kommandant. Euch stehen jetzt alle mittelgroßen Bäume in ganz Draenor zur Verfügung. Das bedeutet mehr Holz pro Baum!", sourceObjectiveStatus = "unverified-source-field" }
quests[36195] = { id = 36195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baum-o-zid", description = "Kommandant, die Ingenieure haben Euch ein Geschenk gemacht. Sie nennen es den \"Baumvernichter XXI der III (Junior)\".\n\nWas man damit machen kann? Bäume vernichten, nehme ich an. Aber vor allem kann man damit große Mengen Bauholz ernten. Wisst Ihr, wie viel Bauholz man aus so einem großen Baum gewinnen kann? Ich auch nicht. Aber ich wette, es ist eine große Menge!\n\nGanz in der Nähe steht ein großer Baum, der darauf wartet, vernichtet zu werden. Warum macht Ihr nicht mal einen Probedurchgang mit dem neuen Gerät? Bringt mir einfach zurück, was Ihr damit abholzen konntet. Ich werde sicher gute Verwendung dafür finden.", sourceObjective = "Besorgt eine Holzprobe von einem großen Baum und bringt sie zu Helge Holzschneider.", progress = "Habt Ihr schon die Holzprobe eingeholt?", completion = "Das ist ja fantastisch! Diese Probe deutet auf massive Bestände von Baumriesen in ganz Draenor hin. Und mit Eurem neuen Baumvernichter XXI dem III (Junior). könnt Ihr diese gewaltigen Baummonster blitzschnell kurz und klein sägen.\n\nUnd, nein, ich hab mir den blöden Namen nicht ausgedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36196] = { id = 36196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Ashran", description = "Seid gegrüßt und willkommen in Ashran.\n\nWendet Euch an Generalin Ushet Wolfstürmer beim Kriegsspeer, um Eure Befehle entgegenzunehmen.", sourceObjective = "Sprecht mit Generalin Ushet Wolfstürmer beim Kriegsspeer.", completion = "Ihr seid gerade erst angekommen? Tja, besser spät als nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[36197] = { id = 36197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatzbereit", description = "Ab an die Front, {name}! Keine Zeit verschwenden. Sprecht mit den Leuten dort. Sie werden Euch einweisen.", sourceObjective = "Sprecht mit Cymre Leuchtklinge, Mare Wildläufer und Zurge.", completion = "Ha, der gute Zurge ist ziemlich sauer, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[36198] = { id = 36198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entdeckung der Artefaktfragmente", description = "Die Artefaktfragmente scheinen von Kreaturen zu stammen, die wir in den Außenbezirken von Ashran gefunden haben.\n\nGeht und tötet alle, die Ihr findet, und bringt mindestens fünf Artefaktfragmente zu Fura der Magierin im Vorposten des Kriegsspeers.", sourceObjective = "Cymre Leuchtklinge im Vorposten des Kriegsspeers möchte, dass Ihr Kreaturen in den Außenbezirken von Ashran abseits der Hauptstraße tötet und 5 Artefaktfragmente zu Fura bringt.", progress = "Sind das Artefaktfragmente, die ich da sehe?", completion = "Gute Arbeit. Solltet Ihr noch mehr Artefaktfragmente finden, bringt sie mir oder anderen, die sie benötigen, um Euren Beitrag zu den Kriegsanstrengungen zu leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[36199] = { id = 36199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondpanzerscheren", description = "Ich werde Euch helfen, aber Ihr müsst mir beweisen, dass Ihr nicht nur gut angeln könnt, sondern auch <ein furchtloser Krieger/eine furchtlose Kriegerin> seid.\n\nDer Strand südöstlich von uns ist voller Mondpanzerkrabbler. Erledigt sie und bringt mir ihre Scheren. Die dürften in diesen Gewässern einen guten Köder abgeben.", sourceObjective = "Zeigt Madari, was Ihr könnt, indem Ihr 4 Mondpanzerscheren sammelt.", progress = "Habt Ihr diese Klauen für mich?", completion = "Nicht schlecht, Reisender, gar nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[36201] = { id = 36201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährungsprobe", description = "Als <Krieger/Kriegerin> habt Ihr gezeigt, was Ihr könnt. Sehen wir doch mal, wie es um Eure Angelkenntnisse bestellt ist. Ich habe einen Köder aus den Mondpanzerscheren gebastelt, die Ihr mir gebracht habt. Angelt damit in diesem Küstengewässer nach Schattenstören.", sourceObjective = "Zeigt Madari, was Ihr könnt, indem Ihr mit seinem Köder 5 Schattenstöre fangt.", progress = "Habt Ihr die Störe gefangen?", completion = "Ich sehe, nicht nur das Kriegshandwerk, auch das Angeln liegt Euch. Ich werde tun, was ich kann, um Euch zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36202] = { id = 36202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln in unserer Garnison", description = "Ihr habt Euren Wert bewiesen, <Reisender/Reisende>. Jetzt nehmt das Abendruhfischertagebuch in Eure Garnison mit und studiert es aufmerksam. Dann werdet Ihr schon bald so viel fangen, wie ihr essen könnt.", sourceObjective = "Kehrt mit dem Angelhandbuch der Abendruh zu Ron Ashton in der Garnison zurück.", progress = "Das können wir als Köder verwenden?!", completion = "Seht Euch nur all die Ideen für Köder in diesem Ding an! Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[36203] = { id = 36203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Gorenei" }
quests[36204] = { id = 36204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Schlinger der Hungrige" }
quests[36205] = { id = 36205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beschädigte Hammer", description = "Dieser kunstvolle Schmiedehammer hat offensichtlich schon bessere Zeiten erlebt.\n\nJetzt ist er beschädigt, dreckig, nur noch ein Schatten seiner selbst.\n\nEins ist gewiss: Sein Vorbesitzer war weder ein Oger noch gehörte er zur Eisernen Horde.\n\nVielleicht weiß jemand im Steinzahnposten, wem der Hammer gehört.", sourceObjective = "Sucht im Steinzahnposten nach dem Vorbesitzer des Hammers.", progress = "Was wollt Ihr, {race}?", completion = "Der Schmiedehammer meines Vaters! Wo habt Ihr ihn gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[36206] = { id = 36206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drachenerzählung", description = "Chromie glaubt, dass sie eine Spur gefunden hat. Wir vermuten, dass Garrosh hier durchgereist ist, als er zum ersten Mal auf Draenor ankam. Aber was ist mit Kairoz? Er muss ganz in der Nähe sein.\n\nChromie wird die Hinweise aufdecken. Haltet Ausschau nach einer Reihe von temporalen Anomalien. Folgt der Spur östlich von hier und sucht Euch einen Weg den Berg hinauf, bis wir Kairozdormu – oder seinen Leichnam – gefunden haben. Viel Glück!", sourceObjective = "Folgt der Hinweisspur den Berg hinauf, bis Ihr Kairozdormu auf der Zeitverlorenen Lichtung entdeckt.", completion = "Damit wäre ein Rätsel gelöst. Gleich nachdem sie auf Draenor ankamen, hat Garrosh seinen Retter umgebracht.\n\nAber er hat die Sache nicht ganz zu Ende gebracht – der Geist des Drachen irrt immer noch umher.\n\nIch hoffe, dass Ihr für den Kampf bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[36207] = { id = 36207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waruk der Frostschmied", description = "Viele sagen, mein Vater war ein legendärer Schmied. Sie haben ihn Waruk den Frostschmied genannt. Sie erzählen Geschichten über seine mächtigen Waffen, die er aus nichts als Eis und Stahl schmiedete. Waruk den Lügenschmied nenne ich ihn.\n\nEr versprach mir, nicht lange fort zu sein. \"Ich muss unsere Truppen unterstützen!\", sagte er.\n\nWarum musste er unbedingt fortgehen? Warum ließ man es zu, dass er gefangen genommen wurde!?\n\nFür zerbrochenes Werkzeug habe ich nicht mehr übrig als für gebrochene Versprechen. Sein Grab liegt östlich von hier. Ihr könnt den Hammer zum Rest seiner nutzlosen Besitztümer legen.", sourceObjective = "Bringt Waruks Hammer zu seinem Grab.", progress = "Seid gegrüßt, {race}. Was bringt Euch zum Grab dieses alten Orcs?", completion = "Wo habt Ihr diesen Hammer gefunden!?", sourceObjectiveStatus = "unverified-source-field" }
quests[36208] = { id = 36208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kristallsplitter", description = "Ich bin froh über den Zeitpunkt Eures Eintreffens.\n\nDie Orcs des Lachenden Schädels praktizieren eine merkwürdige Geistmagie, doch eine ihrer Traditionen könnte in unserer Situation sehr nützlich sein.\n\nKönntet Ihr die Reagenzien sammeln, während ich Vorbereitungen treffe?\n\nAls Erstes benötigen wir Kristalle aus den Überresten von Gorenkadavern. Ihr findet ihre Leichen in der Schlucht.", sourceObjective = "Sammelt 25 Gorenkristalle von Langzahnschlingern.", progress = "Ich habe einige Traditionen des Lachenden Schädels kennen gelernt. Diese Tradition ist noch eine der am wenigsten seltsamen.", completion = "Manche verwenden Gorenkristalle als Waffen. Die daran haftende Säure kann allerdings tödlich sein, auch für den Träger.", sourceObjectiveStatus = "unverified-source-field" }
quests[36209] = { id = 36209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist darunter?", description = "Es ist vollbracht.\n\nMit dieser Verzauberung könnt Ihr Euch nicht nur frei unter den Goren bewegen, sondern Euch auch WIE sie bewegen.\n\nEure Reisen durch die Schlucht sind jetzt einfacher. Ihr habt Zugang zu Orten, die sonst unmöglich zu erreichen wären.\n\nVielleicht gibt es in diesen Tunneln noch mehr Informationen, die wir gegen die Eiserne Horde verwenden könnten.", sourceObjective = "Benutzt die Gorenverkleidung, um Gegenden in Gorgrond zu erkunden.", progress = "Diese Gorenverkleidung stinkt fürchterlich.", completion = "War Eure Suche erfolgreich?", sourceObjectiveStatus = "unverified-source-field" }
quests[36210] = { id = 36210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harte Schale", description = "Ich habe durch meine Beobachtung des Lachenden Schädels bereits einiges erfahren.\n\nMan dachte immer, es sei wegen der Säure, die diese hinterlassen, unmöglich, die Gorentunnel zu durchqueren, aber die Orcs haben einen Ausweg gefunden.\n\nWir brauchen einige Hüllen der Goren aus der Schlucht.\n\nNähert Euch ihren Tunnelausgängen, und die Goren springen heraus. Auf die Art könnt Ihr viele gleichzeitig töten und schneller an die Hüllen kommen.", sourceObjective = "Sammelt 9 Gorenpanzer von Friedhofschlingern.", progress = "Goren scheinen jeden und alles zu fressen, was ihren Weg kreuzt, lebendig oder auch nicht.", completion = "Ah, ja, diese Hüllen sind perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36211] = { id = 36211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Boots Bootstrap" }
quests[36212] = { id = 36212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Wrist Bootstrap" }
quests[36213] = { id = 36213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Ring Bootstrap" }
quests[36214] = { id = 36214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Hands Bootstrap" }
quests[36219] = { id = 36219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Ring des Blutes", description = "Hey, Champion!\n\nIhr wart gerade unterwegs, als ich vorbeigeschaut habe. Ich hab da 'ne feine Sache im Ring des Blutes in Nagrand laufen. 'Ne Menge Oger warten auf den nächsten großen Kampf und es geht um viel Geld. Seid Ihr dabei?\n\nAch, warum frage ich überhaupt. Wer würde sich schon Ruhm, Reichtum und eine ordentliche Schlägerei entgehen lassen? Besucht mich in meinem Versteck, dann besprechen wir Euren großen Auftritt unter vier Augen.\n\n<Auf der beiliegenden Karte ist ein verlassener Ogerturm mit einem Geldsymbol markiert.>", sourceObjective = "Sprecht mit Gurgthock in Gurgthocks Versteck in Nagrand.", completion = "Ich werde Eure kostbare Zeit nicht verschwenden, Champion. Ich biete Euch eine einmalige Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[36220] = { id = 36220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie hart seid Ihr?", description = "Mogor veranstaltet einen ganz besonderen Kampf drüben im Ring des Blutes, um den neuen Blutchampion zu krönen, und ich glaube, Ihr hättet das Zeug dazu!\n\nAllerdings respektieren diese Oger einzig und allein eins: brutale Härte! Der Eingang wird von einem großen Schläger bewacht, der dafür sorgt, dass nur die härtesten Gladiatoren zum Übungsgelände gelangen.\n\nFalls Ihr es ernst meint, dann besiegt den Gladiatorveteranen Lug'dol beim Turm die Straße hoch und bringt seinen Kopf zu Kroggol der Wand. Das sollte ihnen zeigen, aus welchem Holz Ihr geschnitzt seid.", sourceObjective = "Tötet Lug'dol und zeigt seinen Kopf Kroggol der Wand vor dem Gorianischen Übungsgelände.", progress = "Ohne meine Zustimmung wird niemand zum Übungsgelände zugelassen.", completion = "Wenn Ihr Lug'dol besiegt habt, gehört Ihr auf jeden Fall auf das Übungsgelände.\n\nOb Ihr ein Winzling seid oder ein Oger, ist mir vollkommen egal.", sourceObjectiveStatus = "unverified-source-field" }
quests[36221] = { id = 36221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startgebühr", description = "Ihr wollt in den Ring des Blutes? HA! Guter Scherz! Nicht jeder darf im Ring antreten. Es gibt 'ne Startgebühr: fünfzig Blutzeichen.\n\nWie Ihr die bekommt? Oh, <Kleiner/Kleine>, Ihr macht mich fertig!\n\n<Kroggol zeigt Euch einen kleinen, mit Blut verkrusteten Stein.>\n\nDas hier ist Eurer. Der Rest ist bei den anderen auf dem Übungsgelände verteilt. Tötet sie und die Steine gehören Euch. Bringt sie dann zu Wodin dem Trolldiener neben Mogor.\n\nAber nicht mit Mogor reden. Mogor ist der Boss!", sourceObjective = "Sammelt 50 Blutsteine und bringt sie zu Wodin dem Trolldiener.", progress = "Verschwendet nicht meine Zeit, {race}. Was wollt Ihr von Mogor?", completion = "Ihr? Ihr wollt'n Blutchampion werd'n? Hmm.", sourceObjectiveStatus = "unverified-source-field" }
quests[36222] = { id = 36222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Champion des Blutes", description = "Ihr habt genug Blutsteine, um mich von Eurem Können zu überzeugen. Hmm. Ja, Ihr könntet der Champion sein, nach dem Mogor sucht.\n\nIhr seid nur einer von zwei Kandidaten, die die Prüfung des Blutsteins bestanden haben. Ihr zwei werdet nun um die Ehre kämpfen, Blutchampion zu werden.\n\nSprecht mit Gurgthock. Dann werden wir ja sehen, ob Ihr ein Champion seid... oder nur ein weiterer Blutfleck auf dem Arenaboden.", sourceObjective = "Sprecht mit Gurgthock, um an dem Kampf um den Titel des Blutchampions teilzunehmen.", progress = "Nur die Besten krieg'n überhaupt 'ne Chance auf den Titel Blutchampion.", completion = "Ihr habt es geschafft, Mann! Ich hätte nie gedacht, mal so einen Kampf zu erleben!", sourceObjectiveStatus = "unverified-source-field" }
quests[36223] = { id = 36223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst jeden Soldaten zurück", description = "Die Ogron scheinen etwas zu haben, das für die Eiserne Horde wertvoll ist. Ich bin sicher, dass sie das nicht wissen. Wahrscheinlich haben sie nur Langeweile und wollen etwas quälen.\n\nWir könnten sie einfach ihrem Schicksal überlassen, aber wir sollten diesem Hinweis nachgehen. Mit ein wenig Glück können wir die Eiserne Horde davon abhalten, die furchtbarsten Kreaturen Gorgronds in Waffen zu verwandeln.\n\nVersucht, Korporal Thukmar und seine Aufzeichnungen zu finden.", sourceObjective = "Findet Korporal Thukmar und seine Geheimdokumente.", progress = "Erneut habt Ihr gute Arbeit geleistet.", completion = "Wir haben die Aufzeichnungen. Schauen wir mal, was sie über die Strategie unseres Feindes zu sagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36226] = { id = 36226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundet Ashran", description = "Als Scharfseherin kann ich des Kriegsspeers aus noch in die fernsten Winkel Ashrans sehen. Ihr jedoch müsst losziehen und es mit eigenen Augen sehen, {name}.", sourceObjective = "Scharfseherin Mare Wildläufer am Kriegsspeer will, dass Ihr in Ashran Folgendes erkundet: die Straße des Ruhms, den Geschmolzenen Steinbruch, das Schlägerplateau, das Amphitheater der Auslöschung und den Friedhof der Aschehämmer.", completion = "Ihr habt wahrlich das Zeug zu einem echten Entdecker, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[36227] = { id = 36227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Straße des Ruhms", description = "DIE ALLIANZ! <Stampft mit den Füßen auf.> SIE ALLE MÜSSEN SOFORT AUS ASHRAN ENTFERNT WERDEN! MARSCHIERT AUF DER STRASSE DES RUHMS UND TÖTET SO VIELE IHR KÖNNT!\n\nSOFORT!", sourceObjective = "Zurge beim Kriegsspeer will, dass Ihr 5 Mitglieder der Allianz auf der Straße des Ruhms tötet.", completion = "NUR FÜNF? HMPF. NEHMT DIESE BELOHNUNG UND MACHT, DASS IHR WIEDER DA RAUSKOMMT.", sourceObjectiveStatus = "unverified-source-field" }
quests[36228] = { id = 36228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wildnis", description = "WISST IHR, WAS NOCH BESSER IST, ALS ALLIANZABSCHAUM AUF DER STRASSE DES RUHMS ZU TÖTEN?\n\nSIE ÜBERALL ZU TÖTEN. <Lacht.>\n\nGEHT IN DIE AUSSENBEZIRKE VON ASHRAN UND TÖTET JEDES ALLIANZMITGLIED. BRINGT MIR FETZEN IHRER WIDERLICHEN RÜSTUNGEN ALS BEWEIS. JE BLUTIGER, DESTO BESSER.", sourceObjective = "Zurge im Vorposten des Kriegsspeers will, dass Ihr ein Mitglied der Allianz abseits der Hauptstraße tötet und ein Stück seiner Rüstung als Beweis mitbringt.", progress = "ZEIGT MIR DIE RÜSTUNGSFETZEN!", completion = "JA... JA! <Schnüffelt intensiv an dem Rüstungsfetzen.> MMMH, NOCH GANZ FRISCH!", sourceObjectiveStatus = "unverified-source-field" }
quests[36229] = { id = 36229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss - Dr. Zwicky sen." }
quests[36230] = { id = 36230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ruhelose Geist", sourceObjective = "Tötet Kurgthuk den Erbarmungslosen und benutzt Waruks Hammer, um Ausrüstung der Donnerfürsten zu verwerten.", progress = "Und, ist es vollbracht?", completion = "{name}, danke, dass Ihr meinen Tod gerächt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36236] = { id = 36236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kryptische Foliant der Schneiderei", description = "Die verschiedenen Abschnitte des Folianten beschreiben Schneidertechniken, die im Vergleich zu den traditionellen Methoden merkwürdig erscheinen.\n\nDer Name des Verfassers taucht nirgendwo im Folianten auf. Vielleicht weiß jemand in Eurer Garnison mehr über die Herkunft des Buchs.", sourceObjective = "Sprecht mit Aerun in Eurer Garnison.", progress = "Was habt Ihr da, Kindchen?", completion = "Offensichtlich habt Ihr ein ganz besonderes Buch über Schneiderei gefunden.\n\nEs gehört Ameeka, einer hoch angesehenen Schneiderin aus Embaari.", sourceObjectiveStatus = "unverified-source-field" }
quests[36238] = { id = 36238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur eines gebrochenen Herzens", sourceObjective = "Trefft Euch mit Waruk im Steinzahnposten.", progress = "Mein Vater... aber wie habt Ihr...?", completion = "Die ganze Zeit über... war ich so sehr von meiner eigenen Trauer eingenommen.\n\nNicht ein Mal dachte ich daran, wie sehr mein Vater unter unseren Feinden gelitten hat.\n\nTausend Dank, {class}, dass Ihr ihn mir zurückgebracht habt. Bitte erlaubt mir, seinen Hammer zu reparieren.\n\nIm Austausch für all das, was Ihr für uns getan habt, werde ich Euch alles beibringen, was Ihr wissen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[36239] = { id = 36239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geheimnisvoller Ranzen", description = "Ein leerer Ranzen mit einer alten, magischen Aura.\n\nEr sieht recht mitgenommen aus, und im Inneren befinden sich Reste von Kräutern und Pilzen. Vielleicht findet Ihr in Umbrafenn einen Hinweis auf seine Geschichte.", sourceObjective = "Findet den Besitzer des Ranzens.\n\nBereitgestellter Gegenstand:", completion = "Meine Güte. Einer meiner Ranzen! Wo habt Ihr ihn gefunden? Ich habe ihn schon vor Wochen verloren.\n\nIch war so sehr mit meinem Training beschäftigt, dass ich ganz vergaß, Kräuter für Meister Ardule zu sammeln. Ich brauche Eure Hilfe, {name}, falls Ihr so gütig sein wollt. Allerdings muss ich Euch warnen: Es wird extrem gefährlich!\n\nGebt mir kurz den Ranzen, dann stelle ich die Schutzinschrift wieder her, um Euch vor schädlichen Giften zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36240] = { id = 36240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz ruhig", description = "Hervorragend!\n\nSobald Ihr genug Kräuter in der Wildnis gesammelt habt, bringt sie zu mir. Ich werde daraus eine Tinte für Meister Ardule herstellen.\n\nDie Sporensegler und -riesen haben vermutlich, was Ihr sucht.\n\nDoch denkt daran: Seid vorsichtig!", sourceObjective = "Sammelt die Kräuter und kehrt zu Sha'la zurück.", progress = "Ah, genau solche wollte ich haben!", completion = "Das ging schnell, {name}! Und solch eine großzügige Lieferung!\n\nIch habe die Tinte für Euch in ein Fläschchen gefüllt und es versiegelt, aber seid bitte vorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[36241] = { id = 36241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Konservierung", description = "Diese Tinte ist sehr wertvoll für mein Volk. Sie hat die Fähigkeit, alte Texte zu sichern.\n\nMeister Ardule kann alles Weitere erklären. Er ist da drinnen.", sourceObjective = "Bringt die Tinte zu Meister Ardule.", completion = "Meine Güte, {name}. Eure Lieferung...\n\n...Ich weiß nicht, wie ich Euch angemessen danken soll.\n\nDas ist eine beträchtliche Menge Tinte. Ihr habt geholfen, unsere Geschichte für viele kommende Generationen zugänglich zu machen.\n\nVielleicht kann ich Euch danken, indem ich Euch an dem Wissen teilhaben lasse, das Ihr geholfen habt zu bewahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[36242] = { id = 36242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Rauch ist...", description = "Die Brennende Klinge greift Eure Garnison an!\n\nTötet die Meister der Brennenden Klinge, die den Angriff führen, und erstattet dann Kriegsmeister Zog Bericht.", sourceObjective = "Tötet Rag'sla Dumpfklinge, Akatha Feuerlohe und Drek den Feuerrufer.", completion = "Ich wusste, dass es nur eine Frage der Zeit war, bis Azuka handeln würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[36243] = { id = 36243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 001 - Outcast's Basket" }
