quests[36254] = { id = 36254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 002 - Tesska the Broken" }
quests[36255] = { id = 36255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Hochfelsarmschienen", description = "Eine mächtige Magie entströmt diesen Hochfelsarmschienen.\n\nVielleicht kann Euch Yu'rina die Mystikerin, die Rüstmeisterin für Verzauberungen in Eurer Garnison, mehr über diese Armschienen erzählen.", sourceObjective = "Bringt diese Armschienen zu Yu'rina der Mystikerin in Eurer Garnison.\n\nBereitgestellter Gegenstand:", completion = "Interessant... Vor Kurzem hat ein Arakkoa die Garnison aufgesucht. Er fragte nach Rüstungsteilen mit einem starken Zauber wie diesem. Sein Name war Delath.\n\nDer Zauber dieser Armschienen übersteigt meine Fähigkeiten, aber vielleicht kann dieser Delath Euch erzählen, wie man sie replizieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[36256] = { id = 36256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verzauberer der Arakkoa", description = "Der Arakkoa sagte, er würde eine Anomalie auf den Knisternden Ebenen untersuchen, die mit einem weiteren Rüstungsteil zu tun haben könnte.", sourceObjective = "Findet Delath am Rande der Knirschenden Ebenen im Norden.", progress = "Seid gegrüßt, Verzauberer. Ich sehe, dass Ihr mit dieser Kunst vertraut seid. \n\nSehr gut. Vielleicht können wir uns gegenseitig helfen.", completion = "Gehe ich weiterhin recht in der Annahme, dass Ihr ein Artefakt unseres Lands in Eurem Besitz habt?\n\nDarf ich es sehen?\n\nEine von Oru'kais Armschienen... Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[36257] = { id = 36257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Versagen des Schülers", description = "Oru'kai war der erste Ogermagier, der die Verzauberkunst beherrschte. Nach seinem Tod wurden seine Besitztümer über Draenor verstreut. Ich habe sein Szepter zu dem Feld zurückverfolgt, das vor uns liegt.\n\nWie Ihr seht, lässt sich das Szepter wegen seiner Verzauberung nur schwer bergen. Ein zukünftiger Lehrling namens Torag Steinzorn nahm einen von Oru'kais Ringen, um die Verzauberung zu brechen, aber er schaffte es nicht und wurde im Eis gefangen.\n\nBefreit Torag, nehmt den Ring und bringt seine Aufgabe zu Ende. Dann werde ich eine Belohnung in Erwägung ziehen.", sourceObjective = "Findet und befreit Torag aus seinem eisigen Gefängnis.", completion = "Vielen Dank. Ich dachte schon, ich müsste ewig hier bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[36260] = { id = 36260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oru'kais Szepter", description = "Wenn ich gewusst hätte, dass es so gefährlich ist, ein Verzauberer zu sein, wäre ich in Wor'gol geblieben. \n\nHier, nehmt diesen Ring. Der Vogelmann sagte mir, dass ich diesen Ring auf das Szepter anwenden solle, um den Zauber aufzuheben.\n\nBringt ihm das Szepter zurück. Vielleicht wird er ja Euch lehren, was er versprochen hat, mich zu lehren.", sourceObjective = "Nehmt Oru'kais Szepter an Euch und bringt es Delath zurück.", progress = "Habt Ihr es? Bitte gebt es mir.", completion = "Ja... Das ist es, nach so vielen Jahren. Bald werde ich alle Waffen Oru'kais haben.\n\nBringt meinen Ring ebenfalls zurück und ich werde das Versprechen halten, das ich diesem zart besaiteten Orc gegeben habe.\n\nNehmt dieses Buch. Wenn Ihr geschickt seid, könnt Ihr es nutzen, um Draenors Verzauberungen zu entschlüsseln und zu erlernen.\n\nNatürlich werdet Ihr einen vernünftigen Arbeitsplatz benötigen. Hier sind Pläne, denen Ihr hoffentlich folgen könnt.\n\nJetzt geht und haltet Euch von den anderen Waffen fern, denn die gehören mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[36261] = { id = 36261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Vermisster Grunzer", description = "Jetzt, wo sich das Herz von Gorgorek innerhalb der Garnison befindet, müssen wir umso wachsamer sein. Die Brennende Klinge ist für ihre blitzartigen und unvermittelten Angriffe bekannt.\n\nIch habe ein paar der Grunzer zur Bewachung der Festung entsandt. Dul'zak, einer unserer neuen Rekruten, hätte sich bis jetzt schon zurückmelden müssen.", sourceObjective = "Findet Dul'zak.", sourceObjectiveStatus = "unverified-source-field" }
quests[36262] = { id = 36262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ameeka, Schneidermeisterin", description = "Ameeka erschuf dieses Buch, um unsere wertvollsten Handwerkstechniken zu dokumentieren und sie an unsere Kinder weiterzureichen. Sie muss es auf ihren Reisen verloren haben. Sie wird sich sehr freuen, das Buch wiederzusehen.\n\nVon den anderen Dorfbewohnern habe ich gehört, dass sie zuletzt auf der Straße nach Elodor gesehen wurde. Vielleicht findet Ihr sie ja dort.", sourceObjective = "Sprecht mit Ameeka in Elodor.", progress = "Seid gegrüßt, Reisender. Kann ich Euch irgendwie behilflich sein?", completion = "Ist das mein Foliant der Schneiderei? Tatsächlich...! Ich bin ja so froh, dass er noch heil ist! Wie kann ich mich je dafür revanchieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[36265] = { id = 36265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 001 - Stonespite" }
quests[36266] = { id = 36266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kleider am Leibe", description = "Ihr habt mir gegenüber so große Güte bewiesen... Dürfte ich Euch vielleicht um einen weiteren Gefallen bitten?\n\nIn unserem Dorf sammeln wir alte Stoffe, um sie wiederzuverwerten. Wir flicken damit Kleidungsstücke und leichte Rüstungen. Leider wurden die meisten meiner Vorräte bei den jüngsten Angriffen geraubt oder zerstört.\n\nDie Schattenmondkultisten wären sicher nicht so dreist, wenn Ihr ein paar ihrer eigenen Ressourcen für uns stehlen könntet.\n\nWenn Ihr mir ein paar zeremonielle Schattenmondroben bringt, zeige ich Euch meine liebsten Schneidertechniken.", sourceObjective = "Sammelt 10 zeremonielle Roben des Schattenmonds.", progress = "Konntet Ihr die Roben besorgen?", completion = "Erneut erweist Ihr mir große Freundlichkeit.\n\nLasst uns nun beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36267] = { id = 36267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 005 - Durkath Steelmaw" }
quests[36268] = { id = 36268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 007 - Kalos the Bloodbathed" }
quests[36269] = { id = 36269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenzwirn", description = "Ich werde Euch nun die feineren Punkte der Herstellung von Hexenzwirn lehren.\n\nDer Vorgang an sich ist ziemlich einfach. Man muss dabei sorgfältig gewobenen Pelz in das Wundsekret von Gorgrondfliegenfallen tauchen.\n\nNormalerweise müsstet Ihr Euch das Material selbst beschaffen, aber ich konnte dem Schattenmondklan bei ihrem letzten Überfall etwas davon abluchsen.\n\nBedient Euch einfach.", sourceObjective = "Benutzt AmeekasFliegenfallensekret zur Herstellung einer Bahn Hexenzwirn.", progress = "Hattet Ihr Erfolg, mein Lieber?", completion = "Das ist perfekt! Der Stoff und die Magie sind vollkommen ausgewogen und stabil.\n\nEs freut mich, feststellen zu können, dass Ihr die Grundlagen meiner Schneidermethodik erlernt habt. Eure Fähigkeiten und Bereitschaft, neue Techniken zu lernen, nötigen mir Respekt ab.\n\nIch möchte Euch noch ein paar weitere Muster und Materialien geben, von denen ich hoffe, dass sie Euch auf Euren Reisen dienlich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[36271] = { id = 36271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstieg in die Fallenstellerei", description = "Als wir durch das Portal gereist sind, konnten wir keines unserer Tiere mitnehmen. Um Leder und Felle zu produzieren, müssen wir also die einheimischen Tiere mit Fallen fangen und hierher zurückbringen.\n\nWir können eine Menge Leder von den Elekks, oder Felle von den Talbuks direkt hier im Schattenmondtal gewinnen.\n\nHier, nehmt diese Eisenfalle und fangt damit einen erwachsenen verwundeten Talbuk oder Elekk und bringt die Falle hierher zurück, dann werden wir mit dem Arbeitsauftrag beginnen.", sourceObjective = "Benutzt die Eisenfalle, um einen Elekk oder Talbuk im Schattenmondtal zu fangen und erteilt dann in Eurer Scheune einen Arbeitsauftrag.", completion = "Großartige Arbeit, Kommandant! Wir werden Euer Leder oder Fell im Nu bereithalten.\n\nJetzt, da Ihr wisst, wie man eine Falle benutzt, könnt Ihr sie immer wieder verwenden. Wir können allerdings nur eine begrenzte Menge Tiere in der Scheune halten, also überprüft, ob wir genug Platz haben, bevor ihr Fallen aufstellt!", sourceObjectiveStatus = "unverified-source-field" }
quests[36272] = { id = 36272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Versorgung einer Armee", description = "Wir hatten jetzt eine Weile die Gelegenheit, mit diesen Tieren zu arbeiten. Das hat uns in die Lage versetzt, eine brandneue Falle für Euch zu bauen, die Ihr ausprobieren könnt. Sie sollte wesentlich widerstandsfähiger sein als die letzte!\n\nWürde es Euch etwas ausmachen, sie auszuprobieren, Kommandant? Mit der verbesserten Eisenfalle könnt Ihr einige der fleischigsten Tiere wie beispielsweise die großen Eber und die Flussbestien in Gorgrond draußen einfangen. Wir werden dann leckere Steaks aus ihnen machen.", sourceObjective = "Benutzt die verbesserte Falle Eisenfalle, um einen Eber oder eine Flussbestie in Gorgrond zu fangen und erteilt dann in Eurer Scheune einen Arbeitsauftrag.", completion = "Gut gemacht, Kommandant! Wir werden die Steaks gleich auf den Grill legen. Ich kann sie schon riechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[36273] = { id = 36273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut jäten", description = "Wir müssen irgendetwas gegen die Schotlingbedrohung aus dem Zankblattdickicht unternehmen!\n\nZusammen mit Hemet Nesingwary habe ich schon einige der größten und furchteinflößendsten Bestien überhaupt erlegt. Aber noch nie ist mir ein Geschöpf begegnet, das so niederträchtig, bösartig, ruchlos und verkommen war wie ein Schotling!\n\nDiese wilden kleinen Monster verbreiten sich wie Unkraut. Wenn wir nichts unternehmen, werden sie den gesamten Kontinent überrennen!\n\nDringt ins Zankblattdickicht vor und tötet so viele Schotlinge, wie Ihr finden könnt!", sourceObjective = "Tötet 20 Zankblattschotlinge.", completion = "Hervorragende Arbeit, {name}.\n\nIch kann kaum glauben, dass wir lebend aus dem Zankblattdickicht entkommen sind. Ich höre noch immer ihr irres Lachen, als sie über uns hergefallen sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[36274] = { id = 36274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Größere Falle, bessere Ausbeute", description = "Gute Neuigkeiten, Kommandant! Mit den Materialien, die wir hier in Draenor gesammelt haben, konnten wir eine Falle konstruieren, die stark genug ist, selbst die kräftigsten Tiere außer Gefecht zu setzen!\n\nWarum begebt Ihr Euch nicht nach Nagrand und versucht es? Man munkelt, dass die westlichen Ebenen einige der großartigsten Tiere diesseits des Kristallsees beherbergen.\n\nIch muss Euch allerdings warnen: Diese Biester sind zäh. Ihr solltet vielleicht ein paar Freunde mitnehmen.", sourceObjective = "Benutzt die tödliche Eisenfalle, um einen Eisenfellbullen, Terrorzahnalpha oder Sumpflandtrampler einzufangen.", completion = "Das muss ja ein ziemlicher Kampf gewesen sein, Kommandant!\n\nDie Materialien, die wir von Biestern dieser Größe bekommen, werden eine ganze Weile reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[36275] = { id = 36275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Forschen nach der Forschung", description = "Meine Forschungsaufzeichnungen sind verschwunden!\n\nWahrscheinlich sind sie verloren gegangen, als die Schotlinge die Forschungsstation angriffen. Wenn ich die Aufzeichnungen nicht wiederfinde, wird meine gesamte Arbeit umsonst gewesen sein!\n\nHm, ich glaube, ich vermisse auch meinen Rucksack mit Expeditionsvorräten und meine Antifungusstiefel...\n\nWie soll ich ohne Ausrüstung richtige Forschung betreiben können!?\n\nNein, das geht gar nicht.\n\nBitte geht zur Küste von Zangar und sucht nach meinem Eigentum, damit ich weiter Pilze erforschen kann!", sourceObjective = "Bringt Dr. Hadley Ricard die Forschungsaufzeichnungen, die Expeditionsvorräte und Antifungusstiefel.", progress = "Habt Ihr mein fehlendes Eigentum schon gefunden?", completion = "Ah! Ich sehe, Ihr habt meine Aufzeichnungen gefunden... und was ist das? Ihr habt sogar den Rucksack mit Expeditionsvorräten und die Antifungusstiefel mitgebracht!\n\nFantastisch! Jetzt habe ich endlich alles, was ich brauche, um meine Forschung an dem Zangarpilzstamm fortzusetzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[36276] = { id = 36276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 008 - Spawn of Sethe" }
quests[36277] = { id = 36277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximalstufen-Dungeon der Kriegsfürsten - Bonusbelohnungsquest" }
quests[36278] = { id = 36278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 009 - Talonbreaker" }
quests[36279] = { id = 36279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 010 - Poisonmaster Bortusk" }
quests[36280] = { id = 36280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Der Ring des Blutes", description = "Hey, Champion!\n\nIhr wart gerade unterwegs, als ich vorbeigeschaut habe. Ich hab da 'ne feine Sache im Ring des Blutes in Nagrand laufen. 'Ne Menge Oger warten auf den nächsten großen Kampf und es geht um viel Geld. Seid Ihr dabei?\n\nIhr habt doch erst vor Kurzem im Ring der Prüfung die wahre Bedeutung von Schmerz demonstriert, nicht wahr? Jetzt kommt der nächste Schritt auf Eurem Weg zu unendlichem Ruhm! Den dürft Ihr nicht verpassen!\n\nBesucht mich in meinem Versteck, dann besprechen wir Euren großen Auftritt unter Vier Augen.\n\n<Auf der beiliegenden Karte ist ein alter Ogerturm mit einem Geldsymbol markiert.>", sourceObjective = "Sprecht mit Gurgthock in Gurgthocks Versteck in Nagrand.", completion = "Ich werde Eure kostbare Zeit nicht verschwenden, Champion. Ich biete Euch eine einmalige Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
